#requires -Version 5.1
<#
.SYNOPSIS
    Aros Support – välkomstmeddelande, kontakt, formulär och lokal diagnostik.
.DESCRIPTION
    En fristående PS1 för Windows PowerShell 5.1. Bilder, ikoner och licensierade
    typsnitt ingår som Base64. GUI körs i användarsession; installation kan vara tyst.
    Ingen diagnostik skickas utan ett aktivt val i formuläret.
.PARAMETER Mode
    Support (standard): öppna supporten, med välkomstsida om den inte visats.
    Welcome: visa bara om välkomsten inte redan visats för användaren/datorinstallationen.
    Preview: förhandsvisa välkomsten utan att skriva välkomstmarkering.
    Setup: öppna inställningarna. Diagnose: spara en rapport utan GUI.
    Worker är internt och ska inte användas manuellt.
.PARAMETER Install
    Kopiera appen och skapa skrivbords-, Startmeny- och autostartgenväg. Ingen GUI-start.
.PARAMETER Scope
    CurrentUser kräver inte admin. AllUsers kräver elevation vid installation/inställning.
.PARAMETER FlowUrl
    Valfri HTTPS-adress vid -Install. Ange från en skyddad distributionsvariabel.
    Skriv aldrig en riktig flödesadress i den publika PS1-filen.
.PARAMETER OutputPath
    Rapportfil för -Mode Diagnose. Standard: användarens Dokument-mapp.
.EXAMPLE
    powershell.exe -NoProfile -STA -WindowStyle Hidden -File .\Aros-Support.ps1 -Mode Preview
.EXAMPLE
    powershell.exe -NoProfile -File .\Aros-Support.ps1 -Install
.EXAMPLE
    powershell.exe -NoProfile -STA -File .\Aros-Support.ps1 -Mode Setup
.NOTES
    Version 2.0.0-pilot | 2026-10-22
    Spara som UTF-8 med BOM. Ingen installation av externa moduler behövs.
    Power Automate-svar: {"status":"mailSubmitted","requestId":"<samma GUID>"}.
    Ett lyckat svar bekräftar e-poststeget, inte leverans eller ett ticketnummer.
    Typsnittslicenser/källor extraheras till användarens lokala resurser.
#>
[CmdletBinding()]
param(
    [ValidateSet('Support','Welcome','Preview','Setup','Diagnose','Worker')][string]$Mode = 'Support',
    [switch]$Install,
    [switch]$Uninstall,
    [ValidateSet('CurrentUser','AllUsers')][string]$Scope = 'CurrentUser',
    [string]$Customer = '',
    [string]$FlowUrl = '',
    [string]$OutputPath = '',
    [string]$JobFile = '',
    [string]$ResultFile = '',
    [string]$ProgressFile = ''
)
$ErrorActionPreference = 'Stop'
$script:AppVersion = '2.0.0-pilot'
$script:ThisScript = $PSCommandPath

# Ändra bara offentliga kontaktuppgifter här. Flödesadressen sparas via Inställningar.
$script:Aros = @{
    Phone = '021-152550'
    Email = 'servicedesk@arositpartner.se'
    SupportUrl = 'https://arositpartner.se/servicedesk/'
    RemoteSupportUrl = 'https://my.splashtop.eu/sos/packages/download/3K2RJJJZ35TTEU'
}

