# Portable validation/serialization helpers; Windows-specific functions run only when called.
function Write-ArosJsonFile {
    param([string]$Path, [object]$Value)
    $parent = [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Path))
    [void][IO.Directory]::CreateDirectory($parent)
    $temporary = Join-Path $parent ([guid]::NewGuid().ToString('N') + '.tmp')
    try {
        [IO.File]::WriteAllText($temporary, ($Value | ConvertTo-Json -Depth 12), [Text.UTF8Encoding]::new($false))
        if ([IO.File]::Exists($Path)) { [IO.File]::Replace($temporary, $Path, [System.Management.Automation.Language.NullString]::Value) }
        else { [IO.File]::Move($temporary, $Path) }
    } finally { if ([IO.File]::Exists($temporary)) { [IO.File]::Delete($temporary) } }
}

function Read-ArosJsonFile {
    param([string]$Path)
    if (-not [IO.File]::Exists($Path)) { return $null }
    if ([IO.FileInfo]::new($Path).Length -gt 2097152) { throw 'Inställningsfilen är för stor.' }
    return ([IO.File]::ReadAllText($Path, [Text.Encoding]::UTF8) | ConvertFrom-Json -ErrorAction Stop)
}

function Get-ArosHash {
    param([string]$Value)
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Value)))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}

function Test-ArosEndpoint {
    param([string]$Address)
    $uri = $null
    if ([string]::IsNullOrWhiteSpace($Address) -or $Address.Length -gt 8192 -or $Address -match '[\r\n]') { return $false }
    if (-not [Uri]::TryCreate($Address, [UriKind]::Absolute, [ref]$uri)) { return $false }
    return ($uri.Scheme -eq 'https' -and $uri.Host.Length -gt 0 -and $uri.UserInfo.Length -eq 0 -and $uri.Fragment.Length -eq 0)
}

function Get-ArosFormErrors {
    param([System.Collections.IDictionary]$Fields)
    if ([string]::IsNullOrWhiteSpace([string]$Fields.ContactName) -or ([string]$Fields.ContactName).Length -gt 100) { 'Ange ditt namn, högst 100 tecken.' }
    $email = [string]$Fields.ContactEmail
    $validMail = $false
    if ($email.Length -gt 0 -and $email.Length -le 254 -and $email -notmatch '[\r\n\s<>]') {
        try { $mail = [Net.Mail.MailAddress]::new($email); $validMail = ($mail.Address -eq $email -and $mail.Host.Contains('.')) } catch { }
    }
    if (-not $validMail) { 'Ange en giltig e-postadress, till exempel namn@foretag.se.' }
    if (([string]$Fields.ContactPhone).Length -gt 60) { 'Telefonnumret får vara högst 60 tecken.' }
    if (([string]$Fields.Customer).Length -gt 120) { 'Företagsnamnet får vara högst 120 tecken.' }
    if ([string]::IsNullOrWhiteSpace([string]$Fields.Subject) -or ([string]$Fields.Subject).Length -gt 180 -or ([string]$Fields.Subject) -match '[\r\n]') { 'Ange en rubrik på en rad, högst 180 tecken.' }
    if (([string]$Fields.Description).Trim().Length -lt 5 -or ([string]$Fields.Description).Length -gt 8000) { 'Beskriv vad som inte fungerar med 5–8 000 tecken.' }
    if (([string]$Fields.Customer) -match '[\r\n]' -or ([string]$Fields.ContactName) -match '[\r\n]' -or ([string]$Fields.ContactPhone) -match '[\r\n]') { 'Namn, företag och telefonnummer ska stå på varsin rad.' }
}

function New-ArosRequestPayload {
    param([System.Collections.IDictionary]$Fields, [string]$RequestId, [AllowEmptyString()][string]$DiagnosticText = '')
    $errors = @(Get-ArosFormErrors $Fields)
    if ($errors.Count -gt 0) { throw ($errors -join ' ') }
    $guidValue = [guid]::Empty
    if (-not [guid]::TryParse($RequestId, [ref]$guidValue)) { throw 'Ogiltig ärendereferens.' }
    if ($Fields.AttachDiagnostics -and [string]::IsNullOrWhiteSpace($DiagnosticText)) { throw 'Diagnostiken saknas. Kör den igen eller avmarkera Bifoga diagnostik.' }
    $now = [DateTime]::UtcNow.ToString('o')
    $diagLabel = 'Ingen diagnostik bifogad.'
    if ($Fields.AttachDiagnostics) { $diagLabel = 'Diagnostik bifogad efter användarens val.' }
    $description = @(
        'AROS SUPPORT',
        ('Referens: ' + $RequestId),
        ('Skapad (UTC): ' + $now),
        ('Namn: ' + ([string]$Fields.ContactName).Trim()),
        ('E-post: ' + ([string]$Fields.ContactEmail).Trim()),
        ('Telefon: ' + ([string]$Fields.ContactPhone).Trim()),
        ('Företag: ' + ([string]$Fields.Customer).Trim()),
        ('Dator: ' + [string]$Fields.ComputerName),
        ('Kategori: ' + [string]$Fields.Category),
        ('Rubrik: ' + ([string]$Fields.Subject).Trim()),
        '', 'BESKRIVNING', ([string]$Fields.Description).Trim(), '', $diagLabel
    ) -join "`r`n"
    $attachmentText = $description
    if ($Fields.AttachDiagnostics) { $attachmentText += "`r`n`r`n===== DIAGNOSTIK =====`r`n" + $DiagnosticText }
    $encoder = [Text.UTF8Encoding]::new($true)
    [byte[]]$attachmentBytes = $encoder.GetPreamble() + $encoder.GetBytes($attachmentText)
    if ($attachmentBytes.Length -gt 524288) { throw 'Rapporten är för stor för formuläret. Spara den lokalt och kontakta servicedesk.' }
    $subject = '[Aros Support] ' + ([string]$Fields.Subject).Trim()
    return [pscustomobject][ordered]@{
        requestId = $RequestId
        contactEmail = ([string]$Fields.ContactEmail).Trim()
        subject = $subject
        description = $description
        computerName = [string]$Fields.ComputerName
        attachment = [pscustomobject]@{
            name = ('Aros-Support-' + $guidValue.ToString('N').Substring(0, 12) + '.txt')
            contentBase64 = [Convert]::ToBase64String($attachmentBytes)
        }
    }
}

function Test-ArosReceipt {
    param([object]$Response, [string]$RequestId)
    if ($null -eq $Response) { return $false }
    return ([string]$Response.status -ceq 'mailSubmitted' -and [string]$Response.requestId -eq $RequestId)
}

function Test-ArosWelcomeSeen {
    param([string]$Path, [string]$MachineKey)
    try { $state = Read-ArosJsonFile $Path; return ($null -ne $state -and [string]$state.machineKey -eq $MachineKey -and -not [string]::IsNullOrWhiteSpace([string]$state.seenUtc)) }
    catch { return $false }
}

function Set-ArosWelcomeSeen {
    param([string]$Path, [string]$MachineKey)
    Write-ArosJsonFile $Path ([ordered]@{ version=1; machineKey=$MachineKey; seenUtc=[DateTime]::UtcNow.ToString('o') })
}

function Get-ArosMachineKey {
    $baseKey = $null; $key = $null
    try {
        $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, [Microsoft.Win32.RegistryView]::Registry64)
        $key = $baseKey.OpenSubKey('SOFTWARE\Microsoft\Cryptography')
        $value = [string]$key.GetValue('MachineGuid')
        if ([string]::IsNullOrWhiteSpace($value)) { throw 'MachineGuid saknas.' }
        return (Get-ArosHash $value)
    } catch {
        # Normally readable by standard users; profile-local marker still works if registry is restricted.
        return (Get-ArosHash ('computer:' + $env:COMPUTERNAME))
    } finally { if ($key) { $key.Dispose() }; if ($baseKey) { $baseKey.Dispose() } }
}

function Test-ArosAdministrator {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    try { return ([Security.Principal.WindowsPrincipal]::new($identity)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) }
    finally { $identity.Dispose() }
}

function Protect-ArosEndpoint {
    param([string]$Address, [ValidateSet('CurrentUser', 'LocalMachine')][string]$Protection)
    Add-Type -AssemblyName System.Security
    $scopeValue = [Security.Cryptography.DataProtectionScope]::$Protection
    $bytes = [Text.Encoding]::UTF8.GetBytes($Address)
    try { return [Convert]::ToBase64String([Security.Cryptography.ProtectedData]::Protect($bytes, $null, $scopeValue)) }
    finally { [Array]::Clear($bytes, 0, $bytes.Length) }
}

function Unprotect-ArosEndpoint {
    param([string]$ProtectedAddress, [ValidateSet('CurrentUser', 'LocalMachine')][string]$Protection)
    Add-Type -AssemblyName System.Security
    $scopeValue = [Security.Cryptography.DataProtectionScope]::$Protection
    $bytes = [Security.Cryptography.ProtectedData]::Unprotect([Convert]::FromBase64String($ProtectedAddress), $null, $scopeValue)
    try { return [Text.Encoding]::UTF8.GetString($bytes) }
    finally { [Array]::Clear($bytes, 0, $bytes.Length) }
}

function Test-ArosTrustedMachineAcl {
    param([object]$Acl)
    $trusted = @('S-1-5-18','S-1-5-32-544')
    if ($Acl.GetOwner([Security.Principal.SecurityIdentifier]).Value -notin $trusted) { return $false }
    $writes = [Security.AccessControl.FileSystemRights]'Write, Delete, DeleteSubdirectoriesAndFiles, ChangePermissions, TakeOwnership'
    foreach ($rule in $Acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
        if ($rule.AccessControlType -eq [Security.AccessControl.AccessControlType]::Allow -and $rule.IdentityReference.Value -notin $trusted -and ($rule.FileSystemRights -band $writes)) { return $false }
    }
    return $true
}

function Assert-ArosTrustedMachinePath {
    param([string]$Path)
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or -not (Test-ArosTrustedMachineAcl (Get-Acl -LiteralPath $Path))) {
        throw 'Maskininställningarnas ägare eller behörigheter är inte betrodda. En administratör behöver ta bort eller flytta den gamla ProgramData\ArosSupport-mappen och konfigurera den igen.'
    }
}

function Set-ArosMachineFileAcl {
    param([string]$Path)
    if ((Get-Item -LiteralPath $Path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Maskininställningsfilen får inte vara en länk.' }
    $acl = [Security.AccessControl.FileSecurity]::new()
    $acl.SetAccessRuleProtection($true, $false)
    foreach ($sidText in @('S-1-5-18','S-1-5-32-544')) {
        $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($sidText), [Security.AccessControl.FileSystemRights]::FullControl, [Security.AccessControl.AccessControlType]::Allow))
    }
    $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-32-545'), [Security.AccessControl.FileSystemRights]::Read, [Security.AccessControl.AccessControlType]::Allow))
    $acl.SetOwner([Security.Principal.SecurityIdentifier]::new('S-1-5-32-544'))
    Set-Acl -LiteralPath $Path -AclObject $acl
}

function Get-ArosConfiguration {
    param([string]$UserPath, [string]$MachinePath)
    $settings = [pscustomobject]@{ Customer=''; Endpoint=''; Source=''; Warning='' }
    # Local customer/address overrides a machine default. Empty local address falls back to the machine address.
    foreach ($entry in @(@{Path=$MachinePath; Scope='LocalMachine'; Label='datorn'}, @{Path=$UserPath; Scope='CurrentUser'; Label='din användare'})) {
        try {
            if ($entry.Scope -eq 'LocalMachine' -and [IO.File]::Exists($entry.Path)) {
                Assert-ArosTrustedMachinePath ([IO.Path]::GetDirectoryName($entry.Path))
                Assert-ArosTrustedMachinePath $entry.Path
            }
            $config = Read-ArosJsonFile $entry.Path
            if ($null -eq $config) { continue }
            if ([string]$config.Customer) { $settings.Customer = [string]$config.Customer }
            if ([string]$config.FlowUrlProtected) {
                if ([string]$config.Protection -ne $entry.Scope) { throw 'Fel inställningsomfång.' }
                $address = Unprotect-ArosEndpoint $config.FlowUrlProtected $entry.Scope
                if (-not (Test-ArosEndpoint $address)) { throw 'Ogiltig flödesadress.' }
                $settings.Endpoint = $address; $settings.Source = $entry.Label
            }
        } catch { $settings.Warning = 'En sparad formulärinställning kunde inte läsas. Kontrollera Inställningar.' }
    }
    return $settings
}

function Initialize-ArosMachineData {
    param([string]$Path)
    if (-not (Test-ArosAdministrator)) { throw 'Alla användare kräver att installationen/inställningarna körs som administratör.' }
    if ([IO.Directory]::Exists($Path)) { Assert-ArosTrustedMachinePath $Path }
    # Protect our own configuration directory. Do not follow junctions created at these paths.
    $parent = [IO.Path]::GetDirectoryName($Path)
    foreach ($folder in @($parent, $Path)) {
        if ([IO.Directory]::Exists($folder) -and ((Get-Item -LiteralPath $folder -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Inställningsmappen får inte vara en länk eller junction.' }
        [void][IO.Directory]::CreateDirectory($folder)
    }
    $acl = [Security.AccessControl.DirectorySecurity]::new()
    $acl.SetAccessRuleProtection($true, $false)
    $inherit = [Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit'
    $propagate = [Security.AccessControl.PropagationFlags]::None
    foreach ($sidText in @('S-1-5-18', 'S-1-5-32-544')) {
        $sid = [Security.Principal.SecurityIdentifier]::new($sidText)
        $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid, [Security.AccessControl.FileSystemRights]::FullControl, $inherit, $propagate, [Security.AccessControl.AccessControlType]::Allow))
    }
    $users = [Security.Principal.SecurityIdentifier]::new('S-1-5-32-545')
    $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($users, [Security.AccessControl.FileSystemRights]::ReadAndExecute, $inherit, $propagate, [Security.AccessControl.AccessControlType]::Allow))
    $acl.SetOwner([Security.Principal.SecurityIdentifier]::new('S-1-5-32-544'))
    Set-Acl -LiteralPath $Path -AclObject $acl
    $settingsFile = Join-Path $Path 'settings.json'
    if ([IO.File]::Exists($settingsFile)) {
        Assert-ArosTrustedMachinePath $settingsFile
        Set-ArosMachineFileAcl $settingsFile
    }
}

function Save-ArosConfiguration {
    param([string]$Path, [string]$Customer, [AllowEmptyString()][string]$NewEndpoint, [ValidateSet('CurrentUser', 'LocalMachine')][string]$Protection, [switch]$ClearEndpoint)
    if ($Customer.Length -gt 120 -or $Customer -match '[\r\n]') { throw 'Företagsnamnet får vara högst 120 tecken på en rad.' }
    if ($Protection -eq 'LocalMachine') { Initialize-ArosMachineData ([IO.Path]::GetDirectoryName($Path)) }
    $old = Read-ArosJsonFile $Path
    $protected = ''
    if ($null -ne $old -and [string]$old.Protection -eq $Protection) { $protected = [string]$old.FlowUrlProtected }
    if ($ClearEndpoint) { $protected = '' }
    elseif (-not [string]::IsNullOrWhiteSpace($NewEndpoint)) {
        $NewEndpoint = $NewEndpoint.Trim()
        if (-not (Test-ArosEndpoint $NewEndpoint)) { throw 'Ange flödets fullständiga HTTPS-adress, utan användarnamn eller lösenord i adressen.' }
        $protected = Protect-ArosEndpoint $NewEndpoint $Protection
    }
    Write-ArosJsonFile $Path ([ordered]@{ Version=1; Customer=$Customer.Trim(); Protection=$Protection; FlowUrlProtected=$protected })
    if ($Protection -eq 'LocalMachine') { Set-ArosMachineFileAcl $Path }
}

function Invoke-ArosSubmit {
    param([object]$Payload, [string]$Endpoint)
    if (-not (Test-ArosEndpoint $Endpoint)) { throw 'Formuläret saknar en giltig HTTPS-adress.' }
    $result = [pscustomobject]@{ Status='Unknown'; Message='Svaret kunde inte bekräftas. Meddelandet kan redan ha skickats. Ring servicedesk och uppge referensen innan du försöker igen.'; RequestId=[string]$Payload.requestId; HttpStatus=0 }
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    $json = $Payload | ConvertTo-Json -Depth 8 -Compress
    [byte[]]$body = [Text.Encoding]::UTF8.GetBytes($json)
    try {
        # No retry and no redirect: a lost response can occur after the mail action succeeded.
        $response = Invoke-RestMethod -Uri $Endpoint -Method Post -Body $body -ContentType 'application/json; charset=utf-8' -Headers @{Accept='application/json'} -UseBasicParsing -MaximumRedirection 0 -TimeoutSec 55 -ErrorAction Stop
        if (Test-ArosReceipt $response ([string]$Payload.requestId)) {
            $result.Status = 'Sent'
            $result.Message = 'Power Automate har bekräftat att meddelandet har lämnats till e-posttjänsten. Spara referensen nedan. Vid brådskande problem: ring 021-152550.'
        }
    } catch {
        try { if ($_.Exception.Response) { $result.HttpStatus = [int]$_.Exception.Response.StatusCode } } catch { }
        if ($result.HttpStatus -in @(400, 401, 403, 404, 410, 413)) {
            $result.Status = 'Rejected'
            $result.Message = 'Servern returnerade HTTP ' + $result.HttpStatus + '. Kontrollera formulärinställningarna eller kontakta servicedesk. Ingen bekräftelse på skickat meddelande finns.'
        }
        # Do not log Exception.Message: it can contain the signed trigger URL.
    } finally { [Array]::Clear($body, 0, $body.Length) }
    return $result
}


# Windows PowerShell 5.1. Dot-source only; call Invoke-ArosDiagnostics in the
# application's separate, cancellable worker process. No elevation is requested.

function ConvertTo-ArosDiagnosticLine {
    param([object]$Value, [int]$Limit = 240)
    if ($null -eq $Value) { return 'Ej tillgängligt' }
    $text = ([string]$Value -replace '[\x00-\x1F\x7F]', ' ').Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { return 'Ej tillgängligt' }
    if ($text.Length -gt $Limit) { return ($text.Substring(0, $Limit) + '...') }
    return $text
}

function Get-ArosDiagnosticFailure {
    param([object]$Failure)
    $exception = $Failure
    if ($Failure -is [System.Management.Automation.ErrorRecord]) {
        if ($Failure.CategoryInfo.Category -in @('PermissionDenied', 'SecurityError')) {
            return [pscustomobject]@{ Status = 'unavailable'; Detail = 'Åtkomst nekad för aktuell användare.' }
        }
        $exception = $Failure.Exception
    }
    $status = 'error'
    $detail = 'Kontrollen kunde inte slutföras.'
    while ($null -ne $exception) {
        $typeName = $exception.GetType().Name
        if (($exception -is [System.UnauthorizedAccessException]) -or
            ($exception -is [System.Security.SecurityException]) -or
            ($exception.HResult -eq -2147024891)) {
            $status = 'unavailable'; $detail = 'Åtkomst nekad för aktuell användare.'; break
        }
        if (($exception -is [System.TimeoutException]) -or
            ($exception -is [System.OperationCanceledException])) {
            $status = 'timeout'; $detail = 'Kontrollens tidsgräns nåddes.'; break
        }
        if (($exception -is [System.Management.Automation.CommandNotFoundException]) -or
            ($exception -is [System.IO.FileNotFoundException]) -or
            ($exception -is [System.TypeLoadException]) -or
            ($exception -is [System.PlatformNotSupportedException])) {
            $status = 'unavailable'; $detail = 'Datakällan eller funktionen är inte tillgänglig.'; break
        }
        if ($exception -is [System.Net.WebException]) {
            $detail = 'Nätverksfel: ' + $exception.Status.ToString() + '.'
            if ($exception.Status -eq [System.Net.WebExceptionStatus]::Timeout) { $status = 'timeout' }
        } elseif ($exception -is [System.Net.Sockets.SocketException]) {
            $detail = 'Nätverksfel: ' + $exception.SocketErrorCode.ToString() + '.'
        } else {
            $detail = 'Kontrollen kunde inte slutföras (' + $typeName + ').'
        }
        $exception = $exception.InnerException
    }
    [pscustomobject]@{ Status = $status; Detail = $detail }
}

function Invoke-ArosDiagnosticBounded {
    param([string]$Code, [object[]]$Arguments = @(), [int]$TimeoutSeconds = 6)
    $pipeline = $null
    $dispose = $true
    try {
        $pipeline = [System.Management.Automation.PowerShell]::Create()
        [void]$pipeline.AddScript($Code)
        foreach ($argument in $Arguments) { [void]$pipeline.AddArgument($argument) }
        $pending = $pipeline.BeginInvoke()
        if (-not $pending.AsyncWaitHandle.WaitOne($TimeoutSeconds * 1000)) {
            # Stop is asynchronous: a stalled provider must not stall this report.
            # These runspaces start no native programs; worker exit cleans them up.
            $dispose = $false
            try {
                $stopping = $pipeline.BeginStop($null, $null)
                if ($stopping.AsyncWaitHandle.WaitOne(150)) {
                    $pipeline.EndStop($stopping)
                    $dispose = $true
                }
            } catch { }
            return [pscustomobject]@{ Status = 'timeout'; Detail = ('Tidsgränsen {0} sekunder nåddes.' -f $TimeoutSeconds); Output = @() }
        }
        $data = @($pipeline.EndInvoke($pending))
        if ($pipeline.HadErrors -and $pipeline.Streams.Error.Count -gt 0) {
            $failure = Get-ArosDiagnosticFailure $pipeline.Streams.Error[0]
            return [pscustomobject]@{ Status = $failure.Status; Detail = $failure.Detail; Output = $data }
        }
        return [pscustomobject]@{ Status = 'ok'; Detail = ''; Output = $data }
    } catch {
        $failure = Get-ArosDiagnosticFailure $_
        return [pscustomobject]@{ Status = $failure.Status; Detail = $failure.Detail; Output = @() }
    } finally {
        if ($dispose -and $null -ne $pipeline) { $pipeline.Dispose() }
    }
}

function Resolve-ArosDiagnosticDns {
    param([string]$Name, [int]$TimeoutSeconds = 6)
    # No -Server: use the DNS servers configured in Windows. No LLMNR/NetBIOS
    # fallback or hosts-file answer is presented as a successful DNS response.
    $result = Invoke-ArosDiagnosticBounded -TimeoutSeconds $TimeoutSeconds -Arguments @($Name) -Code @'
param($TargetName)
$ErrorActionPreference = 'Stop'
Resolve-DnsName -Name $TargetName -Type A_AAAA -DnsOnly -NoHostsFile -QuickTimeout -ErrorAction Stop |
    Where-Object { -not [string]::IsNullOrWhiteSpace($_.IPAddress) } |
    Select-Object -ExpandProperty IPAddress -Unique
'@
    $addresses = @($result.Output | ForEach-Object { ConvertTo-ArosDiagnosticLine $_ 80 })
    if ($result.Status -ne 'ok') {
        return [pscustomobject]@{ Status = $result.Status; Detail = $result.Detail; Addresses = @() }
    }
    if ($addresses.Count -eq 0) {
        return [pscustomobject]@{ Status = 'warning'; Detail = 'Inget A- eller AAAA-svar returnerades.'; Addresses = @() }
    }
    [pscustomobject]@{ Status = 'ok'; Detail = ($addresses -join ', '); Addresses = $addresses }
}

function Test-ArosDiagnosticHttps {
    param([string]$Uri, [int]$TimeoutSeconds = 8)
    $handler = $null; $client = $null; $request = $null; $response = $null; $cancel = $null
    $previousProtocols = $null
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        Add-Type -AssemblyName System.Net.Http -ErrorAction Stop
        # Some .NET Framework hosts retain an old explicit TLS default. Add TLS
        # 1.2 for this probe, leaving the OS-selected default (zero) untouched.
        $previousProtocols = [System.Net.ServicePointManager]::SecurityProtocol
        if ([int]$previousProtocols -ne 0) {
            [System.Net.ServicePointManager]::SecurityProtocol = $previousProtocols -bor [System.Net.SecurityProtocolType]::Tls12
        }
        $handler = New-Object System.Net.Http.HttpClientHandler
        $handler.AllowAutoRedirect = $false
        $handler.UseCookies = $false
        # Retain the system proxy and normal certificate validation. No credentials,
        # cookies, report content or user identity are supplied to either endpoint.
        $client = New-Object System.Net.Http.HttpClient($handler)
        $client.Timeout = [TimeSpan]::FromSeconds($TimeoutSeconds)
        $request = New-Object System.Net.Http.HttpRequestMessage([System.Net.Http.HttpMethod]::Get, $Uri)
        $cancel = New-Object System.Threading.CancellationTokenSource
        $cancel.CancelAfter($TimeoutSeconds * 1000)
        $pending = $client.SendAsync($request, [System.Net.Http.HttpCompletionOption]::ResponseHeadersRead, $cancel.Token)
        if (-not $pending.Wait($TimeoutSeconds * 1000)) {
            $cancel.Cancel()
            return [pscustomobject]@{ Status = 'timeout'; Detail = ('Inga svarshuvuden inom {0} sekunder.' -f $TimeoutSeconds) }
        }
        $response = $pending.GetAwaiter().GetResult()
        $code = [int]$response.StatusCode
        $elapsed = [Math]::Round($watch.Elapsed.TotalMilliseconds)
        if ($code -ge 200 -and $code -lt 300) {
            $status = 'ok'; $meaning = 'Svarshuvuden mottagna.'
        } elseif ($code -ge 300 -and $code -lt 400) {
            $status = 'ok'; $meaning = 'Omdirigering mottagen; måladressen har inte testats.'
        } elseif ($code -in @(401, 403, 407)) {
            $status = 'blocked'; $meaning = 'Tjänsten eller en proxy nekade åtkomst eller kräver autentisering.'
        } else {
            $status = 'error'; $meaning = 'HTTP-felsvar mottaget; det betyder inte att hela internetanslutningen är nere.'
        }
        [pscustomobject]@{ Status = $status; Detail = ('HTTP {0}, {1} ms. {2}' -f $code, $elapsed, $meaning) }
    } catch {
        if (($null -ne $cancel -and $cancel.IsCancellationRequested) -or $watch.Elapsed.TotalSeconds -ge $TimeoutSeconds) {
            return [pscustomobject]@{ Status = 'timeout'; Detail = ('HTTPS-kontrollens tidsgräns {0} sekunder nåddes.' -f $TimeoutSeconds) }
        }
        $failure = Get-ArosDiagnosticFailure $_
        [pscustomobject]@{ Status = $failure.Status; Detail = ($failure.Detail + ' En brandväggsblockering kan inte fastställas enbart från detta fel.') }
    } finally {
        if ($null -ne $response) { $response.Dispose() }
        if ($null -ne $request) { $request.Dispose() }
        if ($null -ne $cancel) { $cancel.Dispose() }
        if ($null -ne $client) { $client.Dispose() } elseif ($null -ne $handler) { $handler.Dispose() }
        if ($null -ne $previousProtocols) { [System.Net.ServicePointManager]::SecurityProtocol = $previousProtocols }
    }
}

function ConvertFrom-ArosDiagnosticDsregText {
    param([string]$Text)
    $allowed = @('AzureAdJoined', 'EnterpriseJoined', 'DomainJoined', 'WorkplaceJoined', 'NgcSet', 'WamDefaultSet', 'AzureAdPrt', 'EnterprisePrt', 'DeviceAuthStatus')
    $selected = [ordered]@{}
    foreach ($line in ($Text -split '\r?\n')) {
        if ($line -match '^\s*([A-Za-z][A-Za-z0-9]*)\s*:\s*(.*?)\s*$') {
            $name = $Matches[1]; $value = $Matches[2]
            if ($allowed -contains $name) {
                $selected[$name] = ConvertTo-ArosDiagnosticLine $value 120
            }
        }
    }
    [pscustomobject]$selected
}

function Initialize-ArosDiagnosticNativeGuard {
    # The worker owns this job handle for its entire lifetime. Assigning the
    # worker before launching dsregcmd avoids a start/assign race. On worker exit
    # (including parent Kill()), Windows closes the handle and kills descendants.
    # If policy forbids Add-Type or job assignment, skip dsregcmd instead.
    if (-not ('ArosSupport.DiagnosticsJobV2' -as [type])) {
        Add-Type -ErrorAction Stop -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
namespace ArosSupport {
    public static class DiagnosticsJobV2 {
        private static IntPtr lifetimeJob = IntPtr.Zero;
        [StructLayout(LayoutKind.Sequential)]
        private struct BasicLimits {
            public long PerProcessUserTimeLimit, PerJobUserTimeLimit;
            public uint LimitFlags;
            public UIntPtr MinimumWorkingSetSize, MaximumWorkingSetSize;
            public uint ActiveProcessLimit;
            public UIntPtr Affinity;
            public uint PriorityClass, SchedulingClass;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct IoCounters {
            public ulong ReadOperationCount, WriteOperationCount, OtherOperationCount;
            public ulong ReadTransferCount, WriteTransferCount, OtherTransferCount;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct ExtendedLimits {
            public BasicLimits BasicLimitInformation;
            public IoCounters IoInfo;
            public UIntPtr ProcessMemoryLimit, JobMemoryLimit, PeakProcessMemoryUsed, PeakJobMemoryUsed;
        }
        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern IntPtr CreateJobObject(IntPtr attributes, string name);
        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool SetInformationJobObject(IntPtr job, int infoClass, ref ExtendedLimits limits, uint size);
        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool AssignProcessToJobObject(IntPtr job, IntPtr process);
        [DllImport("kernel32.dll")]
        private static extern IntPtr GetCurrentProcess();
        [DllImport("kernel32.dll")]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool CloseHandle(IntPtr handle);
        public static void Ensure() {
            if (lifetimeJob != IntPtr.Zero) return;
            IntPtr job = CreateJobObject(IntPtr.Zero, null);
            if (job == IntPtr.Zero) throw new Win32Exception(Marshal.GetLastWin32Error());
            bool assigned = false;
            try {
                ExtendedLimits limits = new ExtendedLimits();
                limits.BasicLimitInformation.LimitFlags = 0x2000; // KILL_ON_JOB_CLOSE
                if (!SetInformationJobObject(job, 9, ref limits, (uint)Marshal.SizeOf(typeof(ExtendedLimits))))
                    throw new Win32Exception(Marshal.GetLastWin32Error());
                if (!AssignProcessToJobObject(job, GetCurrentProcess()))
                    throw new Win32Exception(Marshal.GetLastWin32Error());
                assigned = true;
                lifetimeJob = job; // Deliberately retained until the worker exits.
            } finally {
                if (!assigned) CloseHandle(job);
            }
        }
    }
}
'@
    }
    [ArosSupport.DiagnosticsJobV2]::Ensure()
}

function Get-ArosDiagnosticEntra {
    param([int]$TimeoutSeconds = 8)
    $process = $null
    try {
        if ([string]::IsNullOrWhiteSpace($env:SystemRoot)) {
            return [pscustomobject]@{ Status = 'unavailable'; Detail = 'dsregcmd är inte tillgängligt.'; Fields = $null }
        }
        $systemFolder = 'System32'
        if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { $systemFolder = 'Sysnative' }
        $executable = Join-Path $env:SystemRoot ($systemFolder + '\dsregcmd.exe')
        if (-not (Test-Path -LiteralPath $executable -PathType Leaf)) {
            return [pscustomobject]@{ Status = 'unavailable'; Detail = 'dsregcmd finns inte på datorn.'; Fields = $null }
        }
        try { Initialize-ArosDiagnosticNativeGuard } catch {
            return [pscustomobject]@{ Status = 'unavailable'; Detail = 'Entra-kontrollen hoppades över eftersom säker processavslutning inte kunde förberedas.'; Fields = $null }
        }
        $start = New-Object System.Diagnostics.ProcessStartInfo
        $start.FileName = $executable
        $start.Arguments = '/status'
        $start.UseShellExecute = $false
        $start.CreateNoWindow = $true
        $start.RedirectStandardOutput = $true
        $start.RedirectStandardError = $true
        $process = New-Object System.Diagnostics.Process
        $process.StartInfo = $start
        [void]$process.Start()
        $stdout = $process.StandardOutput.ReadToEndAsync()
        $stderr = $process.StandardError.ReadToEndAsync()
        if (-not $process.WaitForExit($TimeoutSeconds * 1000)) {
            try { $process.Kill() } catch { }
            [void]$process.WaitForExit(300)
            return [pscustomobject]@{ Status = 'timeout'; Detail = ('dsregcmd överskred {0} sekunder.' -f $TimeoutSeconds); Fields = $null }
        }
        if (-not $stdout.Wait(500)) {
            return [pscustomobject]@{ Status = 'timeout'; Detail = 'dsregcmd avslutades men utdata kunde inte läsas inom tidsgränsen.'; Fields = $null }
        }
        $fields = ConvertFrom-ArosDiagnosticDsregText $stdout.Result
        $status = 'ok'
        $detail = 'Valda statusfält för den användare som kör appen.'
        if ($process.ExitCode -ne 0) { $status = 'warning'; $detail = 'dsregcmd returnerade kod ' + $process.ExitCode + '; eventuella fält är ofullständiga.' }
        if (@($fields.PSObject.Properties).Count -eq 0) { $status = 'unavailable'; $detail = 'Inga av de valda statusfälten kunde läsas.' }
        [pscustomobject]@{ Status = $status; Detail = $detail; Fields = $fields }
    } catch {
        $failure = Get-ArosDiagnosticFailure $_
        [pscustomobject]@{ Status = $failure.Status; Detail = $failure.Detail; Fields = $null }
    } finally {
        if ($null -ne $process) {
            try { if (-not $process.HasExited) { $process.Kill() } } catch { }
            $process.Dispose()
        }
    }
}

function Get-ArosDiagnosticEvents {
    param([string]$LogName, [int]$MaxEvents = 30, [int]$TimeoutSeconds = 7)
    $result = Invoke-ArosDiagnosticBounded -TimeoutSeconds $TimeoutSeconds -Arguments @($LogName, $MaxEvents) -Code @'
param($TargetLog, $Limit)
$ErrorActionPreference = 'Stop'
try {
    Get-WinEvent -FilterHashtable @{ LogName = $TargetLog; Level = @(2, 3); StartTime = (Get-Date).AddHours(-48) } -MaxEvents $Limit -ErrorAction Stop |
        Select-Object Id, ProviderName, Level, TimeCreated
} catch {
    if ($_.FullyQualifiedErrorId -notlike 'NoMatchingEventsFound*') { throw }
}
'@
    [pscustomobject]@{ Status = $result.Status; Detail = $result.Detail; Events = @($result.Output) }
}

function Invoke-ArosDiagnostics {
    [CmdletBinding()]
    param([string]$ProgressPath)

    $ErrorActionPreference = 'Stop'
    $lines = New-Object 'System.Collections.Generic.List[string]'
    $checks = New-Object 'System.Collections.Generic.List[object]'
    $generatedUtc = [DateTime]::UtcNow.ToString('o')
    $labels = @{ ok = 'OK'; warning = 'Observera'; error = 'Fel'; unavailable = 'Ej tillgängligt'; timeout = 'Tidsgräns'; blocked = 'Åtkomst nekad' }

    function Write-ArosDiagnosticProgress([string]$Stage) {
        if (-not [string]::IsNullOrWhiteSpace($ProgressPath)) {
            try { [IO.File]::WriteAllText($ProgressPath, $Stage, (New-Object System.Text.UTF8Encoding($false))) } catch { }
        }
    }
    function Add-ArosDiagnosticLine([string]$Line = '') { [void]$lines.Add($Line) }
    function Add-ArosDiagnosticCheck([string]$Name, [string]$Status, [string]$Detail) {
        [void]$checks.Add([pscustomobject]@{ name = $Name; status = $Status; detail = $Detail })
        Add-ArosDiagnosticLine ('[{0}] {1}: {2}' -f $labels[$Status], $Name, $Detail)
    }
    function Add-ArosDiagnosticFailure([string]$Name, [object]$Failure) {
        $item = Get-ArosDiagnosticFailure $Failure
        Add-ArosDiagnosticCheck $Name $item.Status $item.Detail
    }

    Add-ArosDiagnosticLine 'AROS IT-PARTNER - DIAGNOSTIK'
    Add-ArosDiagnosticLine ('Skapad UTC: ' + $generatedUtc)
    Add-ArosDiagnosticLine 'Kontrollerna beskriver denna körning och är ingen fullständig hälsokontroll.'
    Add-ArosDiagnosticLine 'Uppgifter som inte kan läsas redovisas separat. Inga reparationer görs.'
    Add-ArosDiagnosticLine
    Write-ArosDiagnosticProgress 'Samlar dator- och systemuppgifter...'

    Add-ArosDiagnosticLine 'DATOR OCH ANVÄNDARE'
    $computerName = ConvertTo-ArosDiagnosticLine ([Environment]::MachineName)
    $userName = ConvertTo-ArosDiagnosticLine ([Environment]::UserName)
    $userDomain = ConvertTo-ArosDiagnosticLine ([Environment]::UserDomainName)
    Add-ArosDiagnosticCheck 'Dator och användare' 'ok' ('Dator: {0}; användare: {1}\{2}.' -f $computerName, $userDomain, $userName)
    Add-ArosDiagnosticLine ('PowerShell: {0}; process: {1}-bit.' -f $PSVersionTable.PSVersion, $(if ([Environment]::Is64BitProcess) { '64' } else { '32' }))
    try {
        $os = Get-CimInstance -ClassName Win32_OperatingSystem -Property Caption, Version, BuildNumber, OSArchitecture, LastBootUpTime, TotalVisibleMemorySize, FreePhysicalMemory -OperationTimeoutSec 5 -ErrorAction Stop
        if ($null -eq $os) { throw [InvalidOperationException]::new('No operating system data.') }
        Add-ArosDiagnosticCheck 'Windows' 'ok' ('{0}; version {1}; build {2}; {3}.' -f (ConvertTo-ArosDiagnosticLine $os.Caption), $os.Version, $os.BuildNumber, $os.OSArchitecture)
        if ($null -ne $os.LastBootUpTime) {
            $boot = [DateTime]$os.LastBootUpTime
            $uptime = (Get-Date) - $boot
            Add-ArosDiagnosticLine ('Senaste start: {0}; drifttid: {1} dygn, {2} timmar, {3} minuter.' -f $boot.ToString('yyyy-MM-dd HH:mm:ss zzz'), $uptime.Days, $uptime.Hours, $uptime.Minutes)
        }
        if ($null -ne $os.TotalVisibleMemorySize -and $null -ne $os.FreePhysicalMemory) {
            Add-ArosDiagnosticLine ('RAM tillgängligt för Windows: {0:N1} GiB; ledigt: {1:N1} GiB.' -f ($os.TotalVisibleMemorySize / 1MB), ($os.FreePhysicalMemory / 1MB))
        }
    } catch { Add-ArosDiagnosticFailure 'Windows, drifttid och RAM' $_ }
    try {
        $system = Get-CimInstance -ClassName Win32_ComputerSystem -Property Manufacturer, Model, TotalPhysicalMemory -OperationTimeoutSec 5 -ErrorAction Stop
        if ($null -eq $system) { throw [InvalidOperationException]::new('No computer data.') }
        Add-ArosDiagnosticCheck 'Datormodell' 'ok' ('{0} {1}; installerat RAM: {2:N1} GiB.' -f (ConvertTo-ArosDiagnosticLine $system.Manufacturer), (ConvertTo-ArosDiagnosticLine $system.Model), ($system.TotalPhysicalMemory / 1GB))
    } catch { Add-ArosDiagnosticFailure 'Datormodell' $_ }
    try {
        $bios = Get-CimInstance -ClassName Win32_BIOS -Property SerialNumber -OperationTimeoutSec 5 -ErrorAction Stop
        $serial = ConvertTo-ArosDiagnosticLine $bios.SerialNumber
        if ($serial -eq 'Ej tillgängligt') { Add-ArosDiagnosticCheck 'Serienummer' 'unavailable' $serial }
        else { Add-ArosDiagnosticCheck 'Serienummer' 'ok' $serial }
    } catch { Add-ArosDiagnosticFailure 'Serienummer' $_ }

    Add-ArosDiagnosticLine
    Add-ArosDiagnosticLine 'LOKALA DISKAR'
    Add-ArosDiagnosticLine 'Observera-markering vid mindre än 10 % eller 5 GiB ledigt utrymme.'
    Write-ArosDiagnosticProgress 'Kontrollerar ledigt diskutrymme...'
    try {
        $disks = @(Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType=3' -Property DeviceID, DriveType, FileSystem, Size, FreeSpace -OperationTimeoutSec 5 -ErrorAction Stop)
        if ($disks.Count -eq 0) { Add-ArosDiagnosticCheck 'Diskutrymme' 'unavailable' 'Inga lokala fasta diskar kunde läsas.' }
        foreach ($disk in $disks) {
            if ($null -eq $disk.Size -or $disk.Size -le 0 -or $null -eq $disk.FreeSpace) {
                Add-ArosDiagnosticCheck ('Disk ' + $disk.DeviceID) 'unavailable' 'Storlek eller ledigt utrymme kunde inte läsas.'
                continue
            }
            $percent = 100.0 * $disk.FreeSpace / $disk.Size
            $status = 'ok'
            if ($percent -lt 10 -or $disk.FreeSpace -lt 5GB) { $status = 'warning' }
            Add-ArosDiagnosticCheck ('Disk ' + $disk.DeviceID) $status ('{0:N1} GiB ledigt av {1:N1} GiB ({2:N1} %); {3}.' -f ($disk.FreeSpace / 1GB), ($disk.Size / 1GB), $percent, (ConvertTo-ArosDiagnosticLine $disk.FileSystem))
        }
    } catch { Add-ArosDiagnosticFailure 'Diskutrymme' $_ }

    Add-ArosDiagnosticLine
    Add-ArosDiagnosticLine 'NÄTVERKSKORT OCH INSTÄLLNINGAR'
    Write-ArosDiagnosticProgress 'Läser nätverkskort, IP, DNS och gateway...'
    $adapters = @(); $configs = @(); $networkErrors = New-Object 'System.Collections.Generic.List[string]'
    try {
        $adapters = @(Get-CimInstance -ClassName Win32_NetworkAdapter -Property Index, InterfaceIndex, Name, NetConnectionID, NetConnectionStatus, NetEnabled, PhysicalAdapter -OperationTimeoutSec 5 -ErrorAction Stop)
    } catch { $failure = Get-ArosDiagnosticFailure $_; [void]$networkErrors.Add('Nätverkskort: ' + $failure.Detail) }
    try {
        $configs = @(Get-CimInstance -ClassName Win32_NetworkAdapterConfiguration -Property Index, Description, IPEnabled, IPAddress, IPSubnet, DefaultIPGateway, DNSServerSearchOrder, DHCPEnabled, DHCPServer -OperationTimeoutSec 5 -ErrorAction Stop)
    } catch { $failure = Get-ArosDiagnosticFailure $_; [void]$networkErrors.Add('IP-inställningar: ' + $failure.Detail) }
    if ($adapters.Count -eq 0 -and $configs.Count -eq 0) {
        Add-ArosDiagnosticCheck 'Nätverksinställningar' 'unavailable' ('Inga uppgifter kunde läsas. ' + ($networkErrors -join ' '))
    } else {
        $status = 'ok'
        if ($networkErrors.Count -gt 0) { $status = 'warning' }
        Add-ArosDiagnosticCheck 'Nätverksinställningar' $status ('{0} nätverkskort; {1} IP-konfigurationer. {2}' -f $adapters.Count, $configs.Count, ($networkErrors -join ' '))
        $configByIndex = @{}
        foreach ($config in $configs) { $configByIndex[[string]$config.Index] = $config }
        $adapterByIndex = @{}
        foreach ($adapter in $adapters) { $adapterByIndex[[string]$adapter.Index] = $adapter }
        $indices = @(@($adapters | ForEach-Object { $_.Index }) + @($configs | ForEach-Object { $_.Index }) | Sort-Object -Unique)
        $rows = foreach ($index in $indices) {
            $adapter = $adapterByIndex[[string]$index]
            $config = $configByIndex[[string]$index]
            $connected = $null -ne $adapter -and $adapter.NetConnectionStatus -eq 2
            [pscustomobject]@{ Index = $index; Connected = $connected; Adapter = $adapter; Config = $config }
        }
        $linkStates = @{ 0 = 'Frånkopplat'; 1 = 'Ansluter'; 2 = 'Anslutet'; 3 = 'Kopplar från'; 4 = 'Maskinvara saknas'; 5 = 'Inaktiverat'; 6 = 'Maskinvarufel'; 7 = 'Media frånkopplat'; 8 = 'Autentiserar'; 9 = 'Autentisering klar'; 10 = 'Autentisering misslyckades'; 11 = 'Ogiltig adress'; 12 = 'Inloggningsuppgifter krävs' }
        $shown = 0
        foreach ($row in @($rows | Sort-Object @{ Expression = 'Connected'; Descending = $true }, Index)) {
            if ($shown -ge 48) { Add-ArosDiagnosticLine 'Rapporten begränsas till 48 nätverkskort.'; break }
            $shown++
            $adapter = $row.Adapter; $config = $row.Config
            $name = 'Nätverkskort ' + $row.Index; $link = 'Status saknas'
            if ($null -ne $adapter) {
                $name = ConvertTo-ArosDiagnosticLine $adapter.Name
                if ($null -ne $adapter.NetConnectionStatus -and $linkStates.ContainsKey([int]$adapter.NetConnectionStatus)) { $link = $linkStates[[int]$adapter.NetConnectionStatus] }
                Add-ArosDiagnosticLine ('- {0}; {1}; gränssnitt {2}; namn: {3}.' -f $name, $link, $adapter.InterfaceIndex, (ConvertTo-ArosDiagnosticLine $adapter.NetConnectionID))
            } else { Add-ArosDiagnosticLine ('- {0}; {1}.' -f (ConvertTo-ArosDiagnosticLine $config.Description), $link) }
            if ($null -eq $config) { Add-ArosDiagnosticLine '  IP-inställningar: ej tillgängliga.'; continue }
            $ips = @($config.IPAddress | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
            $subnets = @($config.IPSubnet)
            for ($i = 0; $i -lt $ips.Count; $i++) {
                $mask = 'Ej tillgängligt'
                if ($i -lt $subnets.Count) { $mask = ConvertTo-ArosDiagnosticLine $subnets[$i] 80 }
                Add-ArosDiagnosticLine ('  IP: {0}; mask/prefix: {1}.' -f (ConvertTo-ArosDiagnosticLine $ips[$i] 80), $mask)
            }
            if ($ips.Count -eq 0) { Add-ArosDiagnosticLine '  IP: ingen adress redovisad.' }
            $gateway = @($config.DefaultIPGateway | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ', '
            $dns = @($config.DNSServerSearchOrder | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ', '
            Add-ArosDiagnosticLine ('  Gateway: {0}; DNS: {1}.' -f $(if ($gateway) { $gateway } else { 'Ingen redovisad' }), $(if ($dns) { $dns } else { 'Ingen redovisad' }))
            $dhcp = 'Ej tillgängligt'
            if ($null -ne $config.DHCPEnabled) { if ($config.DHCPEnabled) { $dhcp = 'Ja' } else { $dhcp = 'Nej' } }
            Add-ArosDiagnosticLine ('  DHCP: {0}; DHCP-server: {1}.' -f $dhcp, (ConvertTo-ArosDiagnosticLine $config.DHCPServer 80))
        }
        Add-ArosDiagnosticLine 'Inställningarna ovan kommer från Windows WMI. VPN och namnregler kan påverka vilken DNS-server som faktiskt används.'
    }

    Add-ArosDiagnosticLine
    Add-ArosDiagnosticLine 'DNS OCH HTTPS'
    Add-ArosDiagnosticLine 'Två fasta mål testas. Resultaten gäller dessa mål, denna användare och tidpunkten för kontrollen.'
    foreach ($target in @('arositpartner.se', 'login.microsoftonline.com')) {
        Write-ArosDiagnosticProgress 'Testar DNS med Windows konfigurerade DNS-inställningar...'
        try {
            $dnsResult = Resolve-ArosDiagnosticDns -Name $target -TimeoutSeconds 6
            Add-ArosDiagnosticCheck ('DNS ' + $target) $dnsResult.Status $dnsResult.Detail
        } catch { Add-ArosDiagnosticFailure ('DNS ' + $target) $_ }
    }
    foreach ($target in @('https://arositpartner.se/', 'https://login.microsoftonline.com/')) {
        Write-ArosDiagnosticProgress 'Kontrollerar HTTPS-svar från de två testmålen...'
        try {
            $httpResult = Test-ArosDiagnosticHttps -Uri $target -TimeoutSeconds 8
            Add-ArosDiagnosticCheck ('HTTPS ' + $target) $httpResult.Status $httpResult.Detail
        } catch { Add-ArosDiagnosticFailure ('HTTPS ' + $target) $_ }
    }

    Add-ArosDiagnosticLine
    Add-ArosDiagnosticLine 'MICROSOFT ENTRA OCH ANVÄNDARSTATUS'
    Write-ArosDiagnosticProgress 'Läser valda Entra-statusfält för aktuell användare...'
    try {
        $entra = Get-ArosDiagnosticEntra -TimeoutSeconds 8
        Add-ArosDiagnosticCheck 'Entra-status' $entra.Status $entra.Detail
        if ($null -ne $entra.Fields) {
            foreach ($field in $entra.Fields.PSObject.Properties) { Add-ArosDiagnosticLine ('  {0}: {1}' -f $field.Name, $field.Value) }
        }
        Add-ArosDiagnosticLine 'YES/NO är statusuppgifter, inte ett automatiskt felomdöme. SSO-fält gäller aktuell användare; körning som annan användare ger andra resultat.'
    } catch { Add-ArosDiagnosticFailure 'Entra-status' $_ }

    Add-ArosDiagnosticLine
    Add-ArosDiagnosticLine 'SYSTEM- OCH PROGRAMHÄNDELSER, SENASTE 48 TIMMARNA'
    Add-ArosDiagnosticLine 'Senaste högst 30 fel/varningar per logg. Antalen nedan avser detta urval, inte hela loggen. Inga fullständiga meddelanden samlas in.'
    foreach ($logName in @('System', 'Application')) {
        Write-ArosDiagnosticProgress 'Sammanfattar de senaste system- och programhändelserna...'
        try {
            $eventResult = Get-ArosDiagnosticEvents -LogName $logName -MaxEvents 30 -TimeoutSeconds 7
            if ($eventResult.Status -ne 'ok') {
                Add-ArosDiagnosticCheck ('Händelser ' + $logName) $eventResult.Status $eventResult.Detail
                continue
            }
            $events = @($eventResult.Events)
            if ($events.Count -eq 0) {
                Add-ArosDiagnosticCheck ('Händelser ' + $logName) 'ok' 'Inga matchande fel eller varningar hittades under de senaste 48 timmarna.'
                continue
            }
            Add-ArosDiagnosticCheck ('Händelser ' + $logName) 'warning' ('{0} fel/varningar i urvalet. En logghändelse behöver inte förklara det aktuella problemet.' -f $events.Count)
            $groups = @($events | Group-Object ProviderName, Id, Level | Sort-Object Count -Descending)
            foreach ($group in $groups) {
                $latest = $group.Group | Sort-Object TimeCreated -Descending | Select-Object -First 1
                $level = 'Varning'; if ($latest.Level -eq 2) { $level = 'Fel' }
                $stamp = 'Ej tillgängligt'; if ($null -ne $latest.TimeCreated) { $stamp = ([DateTime]$latest.TimeCreated).ToString('yyyy-MM-dd HH:mm:ss zzz') }
                Add-ArosDiagnosticLine ('  {0}; ID {1}; {2}; antal {3}; senast {4}.' -f (ConvertTo-ArosDiagnosticLine $latest.ProviderName 120), $latest.Id, $level, $group.Count, $stamp)
            }
        } catch { Add-ArosDiagnosticFailure ('Händelser ' + $logName) $_ }
    }

    $ok = @($checks | Where-Object { $_.status -eq 'ok' }).Count
    $attention = @($checks | Where-Object { $_.status -in @('warning', 'error', 'blocked') }).Count
    $missing = @($checks | Where-Object { $_.status -in @('unavailable', 'timeout') }).Count
    $summary = '{0} kontroller klara: {1} OK, {2} med uppgifter att granska, {3} kunde inte slutföras.' -f $checks.Count, $ok, $attention, $missing
    Add-ArosDiagnosticLine
    Add-ArosDiagnosticLine ('SAMMANFATTNING: ' + $summary)
    Write-ArosDiagnosticProgress 'Diagnostiken är klar.'
    [pscustomobject]@{
        GeneratedUtc = $generatedUtc
        Text = ($lines -join "`r`n") + "`r`n"
        Summary = $summary
        Checks = @($checks.ToArray())
    }
}


function Get-ArosResourceBytes {
    param([string]$Name)
    Add-Type -AssemblyName System.IO.Compression
    $archiveStream = [IO.MemoryStream]::new([Convert]::FromBase64String($script:EmbeddedAssets), $false)
    $archive = [IO.Compression.ZipArchive]::new($archiveStream, [IO.Compression.ZipArchiveMode]::Read)
    $source = $null; $destination = $null
    try {
        $entry = $archive.GetEntry($Name)
        if ($null -eq $entry) { throw ('Inbäddad resurs saknas: ' + $Name) }
        $source = $entry.Open(); $destination = [IO.MemoryStream]::new()
        $source.CopyTo($destination)
        return ,$destination.ToArray()
    } finally {
        if ($source) { $source.Dispose() }; if ($destination) { $destination.Dispose() }
        $archive.Dispose(); $archiveStream.Dispose()
    }
}

function New-ArosImage {
    param([byte[]]$Bytes)
    $stream = [IO.MemoryStream]::new($Bytes, $false)
    try {
        $bitmap = [Windows.Media.Imaging.BitmapImage]::new()
        $bitmap.BeginInit(); $bitmap.CacheOption = [Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $bitmap.StreamSource = $stream; $bitmap.EndInit(); $bitmap.Freeze()
        return $bitmap
    } finally { $stream.Dispose() }
}

function Initialize-ArosWindowAssets {
    param($Window, [hashtable]$Controls, [string]$DataDirectory)
    $Controls.imgLogo.Source = New-ArosImage (Get-ArosResourceBytes 'logo.png')
    $Controls.imgWelcomeApps.Source = New-ArosImage (Get-ArosResourceBytes 'apps.png')
    $Controls.imgWelcomeCloud.Source = New-ArosImage (Get-ArosResourceBytes 'cloud.png')
    $Controls.imgWelcomeSupport.Source = New-ArosImage (Get-ArosResourceBytes 'support.png')
    $Window.Icon = New-ArosImage (Get-ArosResourceBytes 'app-icon.png')
    $fontDirectory = Join-Path $DataDirectory 'Assets-3afc06116e82'
    [void][IO.Directory]::CreateDirectory($fontDirectory)
    foreach ($name in @('BigShouldersDisplay-SemiBold.ttf','IBMPlexSans-Regular.ttf','BigShouldersDisplay-OFL.txt','IBMPlexSans-LICENSE.txt','SOURCES.json')) {
        $target = Join-Path $fontDirectory $name
        $bytes = Get-ArosResourceBytes $name
        $write = $true
        if ([IO.File]::Exists($target)) {
            $sha = [Security.Cryptography.SHA256]::Create()
            try { $write = [Convert]::ToBase64String($sha.ComputeHash($bytes)) -ne [Convert]::ToBase64String($sha.ComputeHash([IO.File]::ReadAllBytes($target))) }
            finally { $sha.Dispose() }
        }
        if ($write) { [IO.File]::WriteAllBytes($target, $bytes) }
    }
    $fontUri = [Uri]::new(($fontDirectory.TrimEnd('\') + '\'))
    $Window.Resources['BodyFont'] = [Windows.Media.FontFamily]::new($fontUri, './#IBM Plex Sans')
    $Window.Resources['HeadingFont'] = [Windows.Media.FontFamily]::new($fontUri, './#Big Shoulders Display')
}


function Get-ArosInstallPaths {
    param([ValidateSet('CurrentUser','AllUsers')][string]$InstallScope)
    if ($InstallScope -eq 'AllUsers') {
        $programRoot = $env:ProgramW6432
        if (-not $programRoot) { $programRoot = $env:ProgramFiles }
        $appDirectory = Join-Path $programRoot 'Aros IT-Partner\Support'
        $desktop = [Environment]::GetFolderPath([Environment+SpecialFolder]::CommonDesktopDirectory)
        $programs = [Environment]::GetFolderPath([Environment+SpecialFolder]::CommonPrograms)
        $startup = [Environment]::GetFolderPath([Environment+SpecialFolder]::CommonStartup)
    } else {
        $appDirectory = Join-Path $env:LOCALAPPDATA 'ArosIT\Support\App'
        $desktop = [Environment]::GetFolderPath([Environment+SpecialFolder]::DesktopDirectory)
        $programs = [Environment]::GetFolderPath([Environment+SpecialFolder]::Programs)
        $startup = [Environment]::GetFolderPath([Environment+SpecialFolder]::Startup)
    }
    return [pscustomobject]@{
        AppDirectory=$appDirectory; Script=(Join-Path $appDirectory 'Aros-Support.ps1'); Icon=(Join-Path $appDirectory 'Aros-Support.ico')
        DesktopLink=(Join-Path $desktop 'Aros Support.lnk'); StartLink=(Join-Path $programs 'Aros Support.lnk'); StartupLink=(Join-Path $startup 'Aros Welcome.lnk')
    }
}

function Get-ArosPowerShellPath {
    # Sysnative is only for launching from a 32-bit host; shortcuts always use System32.
    if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { return (Join-Path $env:WINDIR 'Sysnative\WindowsPowerShell\v1.0\powershell.exe') }
    return (Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe')
}

function New-ArosShortcut {
    param($Shell, [string]$Path, [string]$ScriptPath, [string]$IconPath, [string]$LaunchMode)
    [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($Path))
    $shortcut = $Shell.CreateShortcut($Path)
    try {
        $shortcut.TargetPath = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $shortcut.Arguments = '-NoProfile -STA -WindowStyle Hidden -ExecutionPolicy Bypass -File "' + $ScriptPath + '" -Mode ' + $LaunchMode
        $shortcut.WorkingDirectory = [IO.Path]::GetDirectoryName($ScriptPath)
        $shortcut.Description = 'Aros IT-Partner – support, fjärrhjälp och diagnostik'
        $shortcut.IconLocation = $IconPath + ',0'
        $shortcut.WindowStyle = 7
        $shortcut.Save()
    } finally { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($shortcut) }
}

function Install-ArosSupport {
    param([string]$InstallScope, [string]$Company, [string]$Endpoint)
    if ($InstallScope -eq 'AllUsers' -and -not (Test-ArosAdministrator)) { throw 'Starta Windows PowerShell som administratör för -Scope AllUsers.' }
    if ($InstallScope -eq 'CurrentUser' -and [Diagnostics.Process]::GetCurrentProcess().SessionId -eq 0) { throw 'Installera CurrentUser i rätt användarsession. Använd AllUsers för SYSTEM/RMM-distribution.' }
    if (-not [IO.File]::Exists($script:ThisScript)) { throw 'Spara och kör hela PS1-filen från disk innan installation.' }
    if ($Endpoint -and -not (Test-ArosEndpoint $Endpoint)) { throw 'FlowUrl måste vara flödets fullständiga HTTPS-adress.' }
    $paths = Get-ArosInstallPaths $InstallScope
    if ([IO.Directory]::Exists($paths.AppDirectory) -and ((Get-Item -LiteralPath $paths.AppDirectory -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Installationsmappen får inte vara en junction eller länk.' }
    [void][IO.Directory]::CreateDirectory($paths.AppDirectory)
    if ([IO.Path]::GetFullPath($script:ThisScript) -ne [IO.Path]::GetFullPath($paths.Script)) {
        $temporary = Join-Path $paths.AppDirectory ('update-' + [guid]::NewGuid().ToString('N') + '.tmp')
        try {
            [IO.File]::Copy($script:ThisScript, $temporary, $false)
            if ([IO.File]::Exists($paths.Script)) { [IO.File]::Replace($temporary, $paths.Script, [System.Management.Automation.Language.NullString]::Value) }
            else { [IO.File]::Move($temporary, $paths.Script) }
        } finally { if ([IO.File]::Exists($temporary)) { [IO.File]::Delete($temporary) } }
    }
    [IO.File]::WriteAllBytes($paths.Icon, (Get-ArosResourceBytes 'app-icon.ico'))
    if ($InstallScope -eq 'AllUsers') {
        Initialize-ArosMachineData ([IO.Path]::GetDirectoryName($script:MachineConfigPath))
        $configPath = $script:MachineConfigPath; $protection = 'LocalMachine'
    } else { $configPath = $script:UserConfigPath; $protection = 'CurrentUser' }
    if ($Company -or $Endpoint) {
        # Preserve an existing customer on address-only updates.
        if (-not $Company) { $old = Read-ArosJsonFile $configPath; if ($old) { $Company = [string]$old.Customer } }
        Save-ArosConfiguration $configPath $Company $Endpoint $protection
    }
    $shell = New-Object -ComObject WScript.Shell
    try {
        New-ArosShortcut $shell $paths.DesktopLink $paths.Script $paths.Icon 'Support'
        New-ArosShortcut $shell $paths.StartLink $paths.Script $paths.Icon 'Support'
        New-ArosShortcut $shell $paths.StartupLink $paths.Script $paths.Icon 'Welcome'
    } finally { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($shell) }
    Write-Output ('Aros Support installerad: ' + $paths.Script)
    Write-Output 'Välkomsten visas vid nästa inloggning, en gång per användare/datorinstallation. Inställningar och tidigare kvittens bevaras vid uppdatering.'
}

function Uninstall-ArosSupport {
    param([string]$InstallScope)
    if ($InstallScope -eq 'AllUsers' -and -not (Test-ArosAdministrator)) { throw 'Avinstallation för alla användare kräver administratör.' }
    $paths = Get-ArosInstallPaths $InstallScope
    foreach ($file in @($paths.DesktopLink,$paths.StartLink,$paths.StartupLink,$paths.Icon,$paths.Script)) {
        if ([IO.File]::Exists($file)) { [IO.File]::Delete($file) }
    }
    if ([IO.Directory]::Exists($paths.AppDirectory) -and @(Get-ChildItem -LiteralPath $paths.AppDirectory -Force).Count -eq 0) { [IO.Directory]::Delete($paths.AppDirectory) }
    Write-Output 'Aros Support och genvägarna har tagits bort. Inställningar, välkomstmarkering och sparade rapporter finns kvar.'
}


$script:WindowXaml = @'
