        Width="880" Height="720" MinWidth="680" MinHeight="560"
        WindowStartupLocation="CenterScreen" ResizeMode="CanResizeWithGrip"
        Background="#FBF7F3" Foreground="#353535" FontSize="13"
        FontFamily="{DynamicResource BodyFont}"
        UseLayoutRounding="True" SnapsToDevicePixels="True"
        TextOptions.TextFormattingMode="Display"
        KeyboardNavigation.TabNavigation="Cycle">
    <Window.Resources>
        <!-- The host replaces these resources with the bundled local FontFamily objects. -->
        <FontFamily x:Key="BodyFont">IBM Plex Sans, Aptos, Segoe UI</FontFamily>
        <FontFamily x:Key="HeadingFont">Big Shoulders Display, Aptos Display, Segoe UI</FontFamily>
