            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="MinHeight" Value="36"/>
        </Style>
        <Style x:Key="NavigationButton" TargetType="Button" BasedOn="{StaticResource BaseButton}">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="BorderBrush" Value="Transparent"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="Padding" Value="16,12"/>
            <Setter Property="MinHeight" Value="46"/>
            <Setter Property="Margin" Value="0,0,0,6"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="navSurface" CornerRadius="8"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1">
                            <Grid>
                                <Border x:Name="navIndicator" Width="3" CornerRadius="1.5"
                                        HorizontalAlignment="Left" Margin="0,12,0,12"
                                        Background="Transparent"/>
                                <ContentPresenter RecognizesAccessKey="True" Margin="{TemplateBinding Padding}"
                                                  HorizontalAlignment="Left" VerticalAlignment="Center"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="Tag" Value="Active">
                                <Setter Property="AutomationProperties.ItemStatus" Value="Aktuell sida"/>
                                <Setter TargetName="navSurface" Property="Background" Value="{StaticResource Paper}"/>
                                <Setter TargetName="navSurface" Property="BorderBrush" Value="{StaticResource Line}"/>
                                <Setter TargetName="navIndicator" Property="Background" Value="{StaticResource Accent}"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="navSurface" Property="Background" Value="{StaticResource Paper}"/>
                                <Setter TargetName="navSurface" Property="BorderBrush" Value="{StaticResource ControlLine}"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="navSurface" Property="Background" Value="{StaticResource Line}"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="navSurface" Property="Opacity" Value="0.5"/>
                                <Setter Property="Cursor" Value="Arrow"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style TargetType="TextBox">
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Foreground" Value="{StaticResource Ink}"/>
            <Setter Property="Background" Value="#FFFFFF"/>
            <Setter Property="BorderBrush" Value="{StaticResource ControlLine}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="11,9"/>
            <Setter Property="MinHeight" Value="40"/>
            <Setter Property="VerticalContentAlignment" Value="Center"/>
            <Setter Property="SelectionBrush" Value="{StaticResource AccentLight}"/>
            <Setter Property="SelectionOpacity" Value="0.65"/>
            <Setter Property="CaretBrush" Value="{StaticResource Ink}"/>
            <Setter Property="FocusVisualStyle" Value="{StaticResource VisibleFocus}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TextBox">
                        <Border x:Name="fieldSurface" CornerRadius="7"
                                Padding="{TemplateBinding Padding}"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}">
                            <ScrollViewer x:Name="PART_ContentHost" Focusable="False"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsKeyboardFocusWithin" Value="True">
                                <Setter TargetName="fieldSurface" Property="BorderBrush" Value="{StaticResource Ink}"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="fieldSurface" Property="Opacity" Value="0.55"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="PasswordBox">
            <Setter Property="FontSize" Value="14"/>
            <Setter Property="Foreground" Value="{StaticResource Ink}"/>
            <Setter Property="Background" Value="#FFFFFF"/>
            <Setter Property="BorderBrush" Value="{StaticResource ControlLine}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="11,9"/>
            <Setter Property="MinHeight" Value="42"/>
            <Setter Property="FocusVisualStyle" Value="{StaticResource VisibleFocus}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="PasswordBox">
                        <Border x:Name="passwordSurface" CornerRadius="7"
                                Padding="{TemplateBinding Padding}"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}">
                            <ScrollViewer x:Name="PART_ContentHost" Focusable="False"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsKeyboardFocusWithin" Value="True">
                                <Setter TargetName="passwordSurface" Property="BorderBrush" Value="{StaticResource Ink}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="ComboBox">
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Foreground" Value="{StaticResource Ink}"/>
            <Setter Property="Background" Value="#FFFFFF"/>
            <Setter Property="BorderBrush" Value="{StaticResource ControlLine}"/>
            <Setter Property="Padding" Value="10,8"/>
            <Setter Property="MinHeight" Value="40"/>
            <Setter Property="MaxDropDownHeight" Value="240"/>
            <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
            <Setter Property="VerticalContentAlignment" Value="Center"/>
            <Setter Property="FocusVisualStyle" Value="{StaticResource VisibleFocus}"/>
        </Style>
        <Style TargetType="CheckBox">
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Foreground" Value="{StaticResource Ink}"/>
            <Setter Property="MinHeight" Value="38"/>
            <Setter Property="VerticalContentAlignment" Value="Center"/>
            <Setter Property="Padding" Value="6,4"/>
            <Setter Property="FocusVisualStyle" Value="{StaticResource VisibleFocus}"/>
        </Style>
        <Style x:Key="PageScroll" TargetType="ScrollViewer">
            <Setter Property="VerticalScrollBarVisibility" Value="Auto"/>
            <Setter Property="HorizontalScrollBarVisibility" Value="Disabled"/>
            <Setter Property="CanContentScroll" Value="False"/>
            <Setter Property="PanningMode" Value="VerticalOnly"/>
            <Setter Property="Focusable" Value="False"/>
        </Style>
    </Window.Resources>

    <Grid>
        <Grid.RowDefinitions>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        <Grid.ColumnDefinitions>
            <ColumnDefinition Width="200"/>
            <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>

        <Border Grid.Row="0" Grid.Column="0" Background="{StaticResource Beige}"
                BorderBrush="{StaticResource Line}" BorderThickness="0,0,1,0">
            <Grid Margin="14,0,14,18">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>
                <!-- Original logo: visible height >35 DIP, with >=0.5 symbol-height clear space. -->
                <StackPanel Grid.Row="0" Margin="16,28,16,18">
                    <Image x:Name="imgLogo" Width="106" Height="57.30625" Stretch="Uniform"
                           HorizontalAlignment="Left" RenderOptions.BitmapScalingMode="HighQuality"
                           AutomationProperties.Name="Aros IT-Partner"/>
                    <TextBlock x:Name="txtBrandSubline" Text="Support" Style="{StaticResource SectionHeading}"
                               FontSize="23" Margin="0,27,0,0"/>
                </StackPanel>
                <StackPanel Grid.Row="1">
                    <Button x:Name="navHome" Content="_Start" Tag="Active" TabIndex="1"
                            Style="{StaticResource NavigationButton}" AutomationProperties.Name="Support: startsida"/>
                    <Button x:Name="navForm" Content="Skriv ett _ärende" TabIndex="2"
                            Style="{StaticResource NavigationButton}" AutomationProperties.Name="Skriv ett supportärende"/>
                    <Button x:Name="navDiagnostics" Content="Kontrollera _datorn" TabIndex="3"
                            Style="{StaticResource NavigationButton}" AutomationProperties.Name="Kontrollera datorn"/>
                </StackPanel>
                <StackPanel Grid.Row="2">
                    <Border BorderBrush="{StaticResource Line}" BorderThickness="0,1,0,0" Margin="12,12,12,10"/>
                    <TextBlock Text="För tekniker" Style="{StaticResource HintText}" Margin="16,0,0,4"/>
                    <Button x:Name="navSettings" Content="_Inställningar" TabIndex="4"
                            Style="{StaticResource NavigationButton}" Margin="0"
                            AutomationProperties.Name="Inställningar för tekniker"/>
                </StackPanel>
            </Grid>
        </Border>

        <Grid Grid.Row="0" Grid.Column="1">
            <!-- The host changes Visibility; only Home is visible on initial XAML load. -->
            <Grid x:Name="pageWelcome" Visibility="Collapsed">
                <ScrollViewer Style="{StaticResource PageScroll}">
                    <StackPanel Margin="30,28,30,30">
                        <Border Width="34" Height="4" CornerRadius="2" Background="{StaticResource Accent}"
                                HorizontalAlignment="Left" Margin="0,0,0,12"/>
                        <TextBlock x:Name="txtWelcomeHeading" Text="Välkommen tillbaka." Style="{StaticResource HeadingStyle}"/>
                        <TextBlock Text="Några snabba tips efter ominstallationen." Style="{StaticResource BodyText}"
                                   Margin="0,8,0,26"/>

                        <Grid Margin="0,0,0,24">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="46"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                            <Image x:Name="imgWelcomeApps" Width="30" Height="30" Stretch="Uniform"
                                   VerticalAlignment="Top" HorizontalAlignment="Left" Margin="0,4,0,0"
                                   RenderOptions.BitmapScalingMode="HighQuality"/>
                            <StackPanel Grid.Column="1">
                                <TextBlock Text="Dina program" Style="{StaticResource SectionHeading}"/>
                                <TextBlock Text="Hitta och installera tillgängliga appar i Företagsportalen."
                                           Style="{StaticResource BodyText}" Margin="0,5,0,12"/>
                                <Button x:Name="btnWelcomePortal" Content="Öppna Företagsportalen" TabIndex="10"
                                        Style="{StaticResource BaseButton}" HorizontalAlignment="Left"/>
                            </StackPanel>
                        </Grid>
                        <Grid Margin="0,0,0,24">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="46"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                            <Image x:Name="imgWelcomeCloud" Width="30" Height="30" Stretch="Uniform"
                                   VerticalAlignment="Top" HorizontalAlignment="Left" Margin="0,4,0,0"
                                   RenderOptions.BitmapScalingMode="HighQuality"/>
                            <StackPanel Grid.Column="1">
                                <TextBlock Text="Dina filer" Style="{StaticResource SectionHeading}"/>
                                <TextBlock Text="Kontrollera att OneDrive är inloggat med ditt arbetskonto och att filerna synkroniseras."
                                           Style="{StaticResource BodyText}" Margin="0,5,0,12"/>
                                <Button x:Name="btnWelcomeOneDrive" Content="Öppna OneDrive" TabIndex="11"
                                        Style="{StaticResource BaseButton}" HorizontalAlignment="Left"/>
                            </StackPanel>
                        </Grid>
                        <Border Background="{StaticResource Beige}" CornerRadius="12" Padding="18" Margin="0,0,0,22">
                            <Grid>
                                <Grid.ColumnDefinitions><ColumnDefinition Width="46"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                <Image x:Name="imgWelcomeSupport" Width="30" Height="23" Stretch="Uniform"
                                       VerticalAlignment="Top" HorizontalAlignment="Left" Margin="0,5,0,0"
                                       RenderOptions.BitmapScalingMode="HighQuality"/>
                                <StackPanel Grid.Column="1">
                                    <TextBlock Text="Vi finns här för dig." Style="{StaticResource SectionHeading}"/>
                                    <TextBlock Text="Öppna Aros Support när du behöver hjälp eller vill kontrollera datorn."
                                               Style="{StaticResource BodyText}" Margin="0,5,0,0"/>
                                </StackPanel>
                            </Grid>
                        </Border>
                        <Button x:Name="btnWelcomeContinue" Content="Öppna Aros Support" TabIndex="12"
                                Style="{StaticResource PrimaryButton}" HorizontalAlignment="Left"/>
                        <TextBlock Text="Den här välkomsten visas bara första gången." Style="{StaticResource HintText}"
                                   Margin="0,12,0,0"/>
                    </StackPanel>
                </ScrollViewer>
            </Grid>

            <Grid x:Name="pageHome" Visibility="Visible">
                <ScrollViewer Style="{StaticResource PageScroll}">
                    <StackPanel Margin="30,28,30,30">
                        <Border Width="34" Height="4" CornerRadius="2" Background="{StaticResource Accent}"
                                HorizontalAlignment="Left" Margin="0,0,0,12"/>
                        <TextBlock Text="Hur kan vi hjälpa dig?" Style="{StaticResource HeadingStyle}"/>
                        <TextBlock Text="Välj den hjälp du behöver. Vi finns här för dig." Style="{StaticResource BodyText}"
                                   Margin="0,8,0,22"/>

                        <Border Background="{StaticResource Beige}" CornerRadius="12" Padding="20" Margin="0,0,0,20">
                            <StackPanel>
                                <TextBlock Text="Prata med servicedesk" Style="{StaticResource SectionHeading}"/>
                                <TextBlock Text="Ring vid akuta problem eller när du behöver hjälp direkt."
                                           Style="{StaticResource BodyText}" Margin="0,5,0,8"/>
                                <Button x:Name="btnPhone" Content="021-152550" Style="{StaticResource LinkButton}"
                                        FontSize="26" FontFamily="{DynamicResource HeadingFont}" FontWeight="SemiBold"
                                        Padding="7,4" Margin="-7,0,0,0" MinHeight="44" TabIndex="10"
                                        ToolTip="Kopiera telefonnummer" AutomationProperties.Name="Kopiera telefonnummer"/>
                                <TextBlock Text="Vardagar 08–17" Style="{StaticResource HintText}" Margin="0,4,0,0"/>
                                <TextBlock Text="Klicka på numret för att kopiera." Style="{StaticResource HintText}" Margin="0,2,0,0"/>
                            </StackPanel>
                        </Border>

                        <WrapPanel Margin="0,0,0,2">
                            <Button x:Name="btnNewRequest" Content="Skriv ett ärende" Style="{StaticResource PrimaryButton}"
                                    Margin="0,0,10,10" TabIndex="11"/>
                            <Button x:Name="btnRemote" Content="Starta fjärrsupport" Style="{StaticResource BaseButton}"
                                    MinHeight="46" Margin="0,0,0,10" TabIndex="12"
                                    AutomationProperties.HelpText="Starta när en tekniker ber dig."/>
                        </WrapPanel>
                        <TextBlock Text="Starta fjärrsupport när en tekniker ber dig." Style="{StaticResource HintText}"
                                   Margin="0,0,0,24"/>

                        <Border BorderBrush="{StaticResource Line}" BorderThickness="0,1,0,0" Padding="0,20,0,0">
                            <StackPanel>
                                <TextBlock Text="Få en bild av hur datorn mår" Style="{StaticResource SectionHeading}"/>
                                <TextBlock Text="Kör en kontroll av datorn och nätverket. Resultatet kan hjälpa oss att hitta felet."
                                           Style="{StaticResource BodyText}" Margin="0,5,0,12"/>
                                <Button x:Name="btnOpenDiagnostics" Content="Kontrollera datorn" Style="{StaticResource BaseButton}"
                                        HorizontalAlignment="Left" TabIndex="13"/>
                            </StackPanel>
                        </Border>

                        <StackPanel Margin="-7,18,0,0">
                            <Button x:Name="btnEmail" Style="{StaticResource LinkButton}" TabIndex="14"
                                    ToolTip="Öppna ett mejl i ditt e-postprogram" AutomationProperties.Name="Mejla servicedesk">
                                <TextBlock Text="servicedesk@arositpartner.se" TextDecorations="Underline"/>
                            </Button>
                            <Button x:Name="btnWeb" Style="{StaticResource LinkButton}" TabIndex="15"
                                    ToolTip="Öppna servicedesksidan i webbläsaren" AutomationProperties.Name="Besök supportsidan på webben">
                                <TextBlock Text="Besök supportsidan" TextDecorations="Underline"/>
                            </Button>
                        </StackPanel>
                    </StackPanel>
                </ScrollViewer>
            </Grid>

            <Grid x:Name="pageForm" Visibility="Collapsed" Margin="30,28,24,22">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>
                <StackPanel Grid.Row="0" Margin="0,0,6,18">
                    <TextBlock Text="Skriv ett ärende" Style="{StaticResource HeadingStyle}"/>
                    <TextBlock Text="Skicka direkt härifrån. Outlook behövs inte." Style="{StaticResource BodyText}" Margin="0,8,0,0"/>
                </StackPanel>
                <ScrollViewer Grid.Row="1" Style="{StaticResource PageScroll}">
                    <StackPanel Margin="3,3,16,12">
                        <TextBlock Text="Fält märkta med * behöver fyllas i." Style="{StaticResource HintText}" Margin="0,0,0,16"/>
                        <TextBlock Text="En sammanfattning av formuläret skickas som textbilaga. Diagnostik läggs bara till om du väljer det."
                                   Style="{StaticResource HintText}" Margin="0,0,0,16"/>
                        <Label x:Name="lblContactName" Content="Namn *" Target="{Binding ElementName=tbContactName}" Style="{StaticResource FieldLabel}"/>
                        <TextBox x:Name="tbContactName" MaxLength="100" TabIndex="10" Margin="0,0,0,15"
                                 AutomationProperties.LabeledBy="{Binding ElementName=lblContactName}" AutomationProperties.IsRequiredForForm="True"/>
                        <Label x:Name="lblContactEmail" Content="E-post *" Target="{Binding ElementName=tbContactEmail}" Style="{StaticResource FieldLabel}"/>
                        <TextBox x:Name="tbContactEmail" MaxLength="254" TabIndex="11" Margin="0,0,0,15"
                                 AutomationProperties.LabeledBy="{Binding ElementName=lblContactEmail}" AutomationProperties.IsRequiredForForm="True"
                                 AutomationProperties.HelpText="Adressen där vi kan nå dig. Kontrollera att den stämmer."/>
                        <Label x:Name="lblContactPhone" Content="Telefonnummer (valfritt)" Target="{Binding ElementName=tbContactPhone}" Style="{StaticResource FieldLabel}"/>
                        <TextBox x:Name="tbContactPhone" MaxLength="60" TabIndex="12" Margin="0,0,0,15"
                                 AutomationProperties.LabeledBy="{Binding ElementName=lblContactPhone}"/>
                        <Label x:Name="lblCustomer" Content="Företag" Target="{Binding ElementName=tbCustomer}" Style="{StaticResource FieldLabel}"/>
                        <TextBox x:Name="tbCustomer" MaxLength="120" TabIndex="13" Margin="0,0,0,15"
                                 AutomationProperties.LabeledBy="{Binding ElementName=lblCustomer}"/>
                        <Label x:Name="lblCategory" Content="Vad gäller det?" Target="{Binding ElementName=cbCategory}" Style="{StaticResource FieldLabel}"/>
                        <ComboBox x:Name="cbCategory" SelectedIndex="0" TabIndex="14" Margin="0,0,0,15"
                                  AutomationProperties.LabeledBy="{Binding ElementName=lblCategory}">
                            <ComboBoxItem Content="Annat"/>
                            <ComboBoxItem Content="Nätverk"/>
                            <ComboBoxItem Content="Microsoft 365"/>
                            <ComboBoxItem Content="Program"/>
                            <ComboBoxItem Content="Utskrift"/>
                            <ComboBoxItem Content="Dator"/>
                        </ComboBox>
                        <Label x:Name="lblSubject" Content="Ämne *" Target="{Binding ElementName=tbSubject}" Style="{StaticResource FieldLabel}"/>
                        <TextBox x:Name="tbSubject" MaxLength="180" TabIndex="15" Margin="0,0,0,15"
                                 AutomationProperties.LabeledBy="{Binding ElementName=lblSubject}" AutomationProperties.IsRequiredForForm="True"/>
                        <Label x:Name="lblDescription" Content="Beskriv problemet *" Target="{Binding ElementName=tbDescription}" Style="{StaticResource FieldLabel}"/>
                        <TextBox x:Name="tbDescription" AcceptsReturn="True" AcceptsTab="False" Height="148" MaxLength="8000"
                                 TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled"
                                 VerticalContentAlignment="Top" TabIndex="16" Margin="0,0,0,7"
                                 AutomationProperties.LabeledBy="{Binding ElementName=lblDescription}" AutomationProperties.IsRequiredForForm="True"
                                 AutomationProperties.HelpText="Beskriv vad som händer, när det började och vad du redan har provat."/>
                        <TextBlock Text="Vad händer, när började det och vad har du redan provat?" Style="{StaticResource HintText}" Margin="0,0,0,20"/>
                        <Border Background="{StaticResource Beige}" CornerRadius="10" Padding="14">
                            <StackPanel>
                                <CheckBox x:Name="chkAttachDiagnostics" IsChecked="False" TabIndex="17"
                                          AutomationProperties.Name="Bifoga datorns diagnostik"
                                          AutomationProperties.HelpText="Rapporten skickas bara när den här rutan är markerad.">
                                    <TextBlock Text="Bifoga datorns diagnostik"/>
                                </CheckBox>
                                <TextBlock Text="Rapporten kan innehålla datornamn samt nätverks- och systeminformation. Kör och granska den innan du väljer att bifoga."
                                           Style="{StaticResource HintText}" Margin="0,4,0,12"/>
                                <Button x:Name="btnFormDiagnostics" Content="Kör och granska diagnostik" Style="{StaticResource BaseButton}"
                                        HorizontalAlignment="Left" TabIndex="18"/>
                            </StackPanel>
                        </Border>
                    </StackPanel>
                </ScrollViewer>
                <Border Grid.Row="2" BorderBrush="{StaticResource Line}" BorderThickness="0,1,0,0" Padding="0,13,6,0" Margin="0,8,0,0">
                    <StackPanel>
                        <TextBlock x:Name="txtFormStatus" Text="" Style="{StaticResource HintText}" Margin="0,0,0,7"
                                   AutomationProperties.LiveSetting="Polite"/>
                        <TextBlock x:Name="txtRequestReference" Text="" FontSize="13" TextWrapping="Wrap" Margin="0,0,0,7"
                                   AutomationProperties.LiveSetting="Polite"/>
                        <WrapPanel>
                            <Button x:Name="btnSend" Content="Skicka till servicedesk" Style="{StaticResource PrimaryButton}"
                                    TabIndex="19" Margin="0,0,10,6"/>
                            <Button x:Name="btnClearForm" Content="Rensa formuläret" Style="{StaticResource BaseButton}"
                                    MinHeight="46" TabIndex="20" Margin="0,0,0,6"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
            </Grid>

            <Grid x:Name="pageDiagnostics" Visibility="Collapsed" Margin="30,28,30,24">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>
                <StackPanel Grid.Row="0" Margin="0,0,0,18">
                    <TextBlock Text="Kontrollera datorn" Style="{StaticResource HeadingStyle}"/>
                    <TextBlock Text="En översikt av datorn och nätverket som du kan läsa själv eller dela med servicedesk."
                               Style="{StaticResource BodyText}" Margin="0,8,0,0"/>
                </StackPanel>
                <WrapPanel Grid.Row="1">
                    <Button x:Name="btnRunDiagnostics" Content="Kör diagnostik" Style="{StaticResource PrimaryButton}"
                            TabIndex="10" Margin="0,0,10,8"/>
                    <Button x:Name="btnCancelDiagnostics" Content="Avbryt" Style="{StaticResource BaseButton}" MinHeight="46"
                            IsEnabled="False" TabIndex="11" Margin="0,0,0,8"/>
                </WrapPanel>
                <TextBlock x:Name="txtDiagnosticStatus" Grid.Row="2" Text="Ingen kontroll har körts ännu."
                           Style="{StaticResource HintText}" Margin="0,3,0,10" MaxHeight="36"
                           TextTrimming="CharacterEllipsis" ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}"
                           AutomationProperties.LiveSetting="Polite"/>
                <TextBox x:Name="tbDiagnosticReport" Grid.Row="3" IsReadOnly="True" IsReadOnlyCaretVisible="True"
                         AcceptsReturn="True" AcceptsTab="False" TextWrapping="NoWrap" MinHeight="100"
                         VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" VerticalContentAlignment="Top"
                         FontFamily="Consolas, Courier New" FontSize="12" Background="#FFFFFF" Padding="14"
                         Text="Kör diagnostik för att visa rapporten här." TabIndex="12"
                         AutomationProperties.Name="Diagnostikrapport" AutomationProperties.HelpText="Skrivskyddad rapport. Du kan markera och kopiera text."/>
                <StackPanel Grid.Row="4" Margin="0,12,0,0">
                    <WrapPanel>
                        <Button x:Name="btnSaveDiagnostics" Content="Spara rapport" Style="{StaticResource BaseButton}"
                                IsEnabled="False" TabIndex="13" Margin="0,0,10,6"/>
                        <Button x:Name="btnCopyDiagnostics" Content="Kopiera rapport" Style="{StaticResource BaseButton}"
                                IsEnabled="False" TabIndex="14" Margin="0,0,0,6"/>
                    </WrapPanel>
                    <TextBlock Text="Vill du skicka rapporten? Välj Skriv ett ärende och markera Bifoga datorns diagnostik."
                               Style="{StaticResource HintText}" Margin="0,4,0,0"/>
                </StackPanel>
            </Grid>

            <Grid x:Name="pageSettings" Visibility="Collapsed">
                <ScrollViewer Style="{StaticResource PageScroll}">
                    <StackPanel Margin="30,28,30,30">
                        <TextBlock Text="Inställningar" Style="{StaticResource HeadingStyle}"/>
                        <TextBlock Text="För tekniker som förbereder Aros Support." Style="{StaticResource BodyText}" Margin="0,8,0,24"/>
                        <Label x:Name="lblSettingCustomer" Content="Företag" Target="{Binding ElementName=tbSettingCustomer}" Style="{StaticResource FieldLabel}"/>
                        <TextBox x:Name="tbSettingCustomer" MaxLength="120" TabIndex="10" Margin="0,0,0,7"
                                 AutomationProperties.LabeledBy="{Binding ElementName=lblSettingCustomer}"/>
                        <TextBlock Text="Förifylls i supportformuläret och kan ändras där." Style="{StaticResource HintText}" Margin="0,0,0,22"/>
                        <Label x:Name="lblFlowUrl" Content="Power Automate-adress (HTTPS)" Target="{Binding ElementName=pbFlowUrl}" Style="{StaticResource FieldLabel}"/>
                        <PasswordBox x:Name="pbFlowUrl" TabIndex="11" MaxLength="8192"
                                     AutomationProperties.LabeledBy="{Binding ElementName=lblFlowUrl}"
                                     AutomationProperties.HelpText="Klistra in hela adressen från HTTP-utlösaren. Värdet är dolt."/>
                        <TextBlock x:Name="txtSettingsHint" Text="Klistra in hela adressen från HTTP-utlösaren i Power Automate. Adressen döljs i fältet."
                                   Style="{StaticResource HintText}" Margin="0,8,0,20"/>
                        <WrapPanel Margin="0,0,0,12">
                            <Button x:Name="btnSaveSettings" Content="Spara inställningar" Style="{StaticResource PrimaryButton}"
                                    TabIndex="12" Margin="0,0,10,8"/>
                            <Button x:Name="btnClearEndpoint" Content="Ta bort mottagare" Style="{StaticResource BaseButton}" MinHeight="46"
                                    TabIndex="13" Margin="0,0,0,8"/>
                        </WrapPanel>
                        <Border Background="{StaticResource Beige}" CornerRadius="10" Padding="15">
                            <TextBlock x:Name="txtEndpointStatus" Text="Ingen mottagare sparad." FontSize="13"
                                       TextWrapping="Wrap" AutomationProperties.LiveSetting="Polite"/>
                        </Border>
                    </StackPanel>
                </ScrollViewer>
            </Grid>
        </Grid>

        <Border Grid.Row="1" Grid.ColumnSpan="2" Background="{StaticResource Beige}"
                BorderBrush="{StaticResource Line}" BorderThickness="0,1,0,0" Padding="20,9,24,9">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                <TextBlock Grid.Column="0" Text="Dator" Style="{StaticResource HintText}" VerticalAlignment="Center" Margin="0,0,10,0"/>
                <TextBlock x:Name="txtComputerName" Grid.Column="1" Text="—" MaxWidth="210" TextWrapping="NoWrap"
                           TextTrimming="CharacterEllipsis" FontSize="12" VerticalAlignment="Center"
                           AutomationProperties.Name="Datornamn"/>
                <Button x:Name="btnCopyComputer" Grid.Column="2" Content="Kopiera" Style="{StaticResource LinkButton}"
                        FontSize="12" MinHeight="32" Padding="9,5" Margin="8,0,12,0" TabIndex="90"
                        ToolTip="Kopiera datornamnet" AutomationProperties.Name="Kopiera datornamnet"/>
                <TextBlock x:Name="txtFooterStatus" Grid.Column="3" Text="Redo" Style="{StaticResource HintText}"
                           TextAlignment="Right" VerticalAlignment="Center" MaxHeight="36" TextTrimming="CharacterEllipsis"
                           ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}" AutomationProperties.LiveSetting="Polite"/>
            </Grid>
        </Border>
    </Grid>
</Window>
'@


function Show-ArosPage {
    param([ValidateSet('Welcome','Home','Form','Diagnostics','Settings')][string]$Name)
    foreach ($page in @('Welcome','Home','Form','Diagnostics','Settings')) { $ui[('page' + $page)].Visibility = [Windows.Visibility]::Collapsed }
    $ui[('page' + $Name)].Visibility = [Windows.Visibility]::Visible
    foreach ($nav in @('Home','Form','Diagnostics','Settings')) { $ui[('nav' + $nav)].Tag = '' }
    if ($Name -ne 'Welcome') { $ui[('nav' + $Name)].Tag = 'Active' }
    $script:CurrentPage = $Name
}

function Set-ArosFooter { param([string]$Text) $ui.txtFooterStatus.Text = $Text }

function Invoke-ArosUiAction {
    param([scriptblock]$Action)
    try { & $Action }
    catch {
        # Exceptions from configuration/network may contain a secret URL. UI uses a bounded generic message.
        Set-ArosFooter 'Åtgärden kunde inte slutföras. Försök igen eller ring 021-152550.'
        [void][Windows.MessageBox]::Show($window, 'Åtgärden kunde inte slutföras. Kontrollera att du har åtkomst till filen eller mappen och försök igen. Du kan alltid ringa 021-152550.', 'Aros Support', 'OK', 'Warning')
    }
}

function Copy-ArosText {
    param([string]$Text, [string]$Notice)
    [Windows.Clipboard]::SetText($Text)
    Set-ArosFooter $Notice
}

function Open-ArosLink {
    param([string]$Address)
    $uri = [Uri]$Address
    if (-not $uri.IsAbsoluteUri -or $uri.Scheme -notin @('https','mailto','companyportal')) { throw 'Länktypen stöds inte.' }
    $info = [Diagnostics.ProcessStartInfo]::new()
    $info.FileName = $Address; $info.UseShellExecute = $true
    try { $p = [Diagnostics.Process]::Start($info); if ($p) { $p.Dispose() } }
    catch {
        if ($uri.Scheme -eq 'companyportal') { Set-ArosFooter 'Öppna Företagsportalen i Start-menyn. Kontakta oss om den saknas.' }
        else { Copy-ArosText $Address 'Länken kunde inte öppnas. Den är kopierad så att du kan klistra in den själv.' }
    }
}

function Refresh-ArosConfiguration {
    $script:Configuration = Get-ArosConfiguration $script:UserConfigPath $script:MachineConfigPath
    $displayConfiguration = $script:Configuration
    if ($Scope -eq 'AllUsers') { $displayConfiguration = Get-ArosConfiguration -UserPath '' -MachinePath $script:MachineConfigPath }
    $ui.tbSettingCustomer.Text = $displayConfiguration.Customer
    if (-not $ui.tbCustomer.Text) { $ui.tbCustomer.Text = $script:Configuration.Customer }
    if ($displayConfiguration.Warning) { $ui.txtEndpointStatus.Text = $displayConfiguration.Warning }
    elseif ($displayConfiguration.Endpoint) { $ui.txtEndpointStatus.Text = 'En formuläradress finns sparad för ' + $displayConfiguration.Source + '. Adressen visas inte här.' }
    else { $ui.txtEndpointStatus.Text = 'Ingen formuläradress är sparad för detta omfång ännu.' }
    if ($script:Configuration.Warning) {
        $ui.txtFormStatus.Text = 'Formulärinställningarna behöver kontrolleras. Ring 021-152550 eller kontakta IT.'
    } elseif ($script:Configuration.Endpoint) {
        if (-not $script:ActiveJob) { $ui.txtFormStatus.Text = 'Beskriv problemet och kontrollera din e-postadress innan du skickar.' }
    } else {
        $ui.txtFormStatus.Text = 'Formuläret behöver aktiveras av IT under Inställningar. Du kan ringa eller använda e-post under tiden.'
    }
    if ($Scope -eq 'AllUsers') {
        $ui.txtSettingsHint.Text = 'Inställningarna sparas för alla användare på denna dator. En personlig inställning kan ersätta datorns standard. Klistra in den fullständiga HTTPS-adressen från ert testade Power Automate-flöde. En tom ruta behåller befintlig adress.'
    } else {
        $ui.txtSettingsHint.Text = 'Inställningarna sparas för din Windows-användare. Klistra in den fullständiga HTTPS-adressen från ert testade Power Automate-flöde. En tom ruta behåller befintlig adress. För företagsdistribution kan IT ange en standard för hela datorn.'
    }
    Update-ArosBusyControls
}

function Update-ArosBusyControls {
    $busy = $null -ne $script:ActiveJob
    foreach ($name in @('tbContactName','tbContactEmail','tbContactPhone','tbCustomer','tbSubject','tbDescription','cbCategory','chkAttachDiagnostics','btnClearForm','btnSaveSettings','btnClearEndpoint','pbFlowUrl','tbSettingCustomer')) { $ui[$name].IsEnabled = -not $busy }
    $ui.btnRunDiagnostics.IsEnabled = -not $busy
    $ui.btnFormDiagnostics.IsEnabled = -not $busy
    $ui.btnCancelDiagnostics.IsEnabled = $busy -and $script:ActiveJob.Operation -eq 'Diagnostics'
    $hasReport = $null -ne $script:DiagnosticReport -and -not [string]::IsNullOrWhiteSpace([string]$script:DiagnosticReport.Text)
    $ui.btnSaveDiagnostics.IsEnabled = $hasReport -and -not $busy
    $ui.btnCopyDiagnostics.IsEnabled = $hasReport -and -not $busy
    $ui.btnSend.IsEnabled = (-not $busy -and -not $script:Configuration.Warning -and (Test-ArosEndpoint $script:Configuration.Endpoint))
    if ($busy -and $script:ActiveJob.Operation -eq 'Send') { $ui.btnSend.Content = 'Skickar…' }
    elseif ($busy -and $script:ActiveJob.Purpose -eq 'FormSend') { $ui.btnSend.Content = 'Samlar diagnostik…' }
    else { $ui.btnSend.Content = 'Skicka till servicedesk' }
}

function Get-ArosFormFields {
    $category = 'Annat'
    if ($ui.cbCategory.SelectedItem) { $category = [string]$ui.cbCategory.SelectedItem.Content }
    return [ordered]@{
        ContactName=$ui.tbContactName.Text.Trim(); ContactEmail=$ui.tbContactEmail.Text.Trim()
        ContactPhone=$ui.tbContactPhone.Text.Trim(); Customer=$ui.tbCustomer.Text.Trim()
        Subject=$ui.tbSubject.Text.Trim(); Description=$ui.tbDescription.Text.Trim()
        Category=$category; ComputerName=$env:COMPUTERNAME; AttachDiagnostics=[bool]$ui.chkAttachDiagnostics.IsChecked
    }
}

function New-ArosWorkerJob {
    param([ValidateSet('Diagnostics','Send')][string]$Operation, [string]$Purpose, [object]$Payload = $null)
    $directory = Join-Path (Join-Path $script:DataDirectory 'Jobs') ([guid]::NewGuid().ToString('N'))
    [void][IO.Directory]::CreateDirectory($directory)
    $inputPath = Join-Path $directory 'request.json'
    $resultPath = Join-Path $directory 'result.json'
    $progressPath = Join-Path $directory 'progress.txt'
    Write-ArosJsonFile $inputPath ([ordered]@{Operation=$Operation; Payload=$Payload})
    $info = [Diagnostics.ProcessStartInfo]::new()
    $info.FileName = Get-ArosPowerShellPath
    $info.Arguments = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $script:ThisScript + '" -Mode Worker -JobFile "' + $inputPath + '" -ResultFile "' + $resultPath + '" -ProgressFile "' + $progressPath + '"'
    $info.UseShellExecute = $false; $info.CreateNoWindow = $true
    $info.WorkingDirectory = [IO.Path]::GetDirectoryName($script:ThisScript)
    $process = [Diagnostics.Process]::new(); $process.StartInfo = $info
    try {
        if (-not $process.Start()) { throw 'Bakgrundsprocessen kunde inte startas.' }
        $limit = 120; if ($Operation -eq 'Send') { $limit = 75 }
        return [pscustomobject]@{Operation=$Operation; Purpose=$Purpose; Process=$process; Directory=$directory; ResultPath=$resultPath; ProgressPath=$progressPath; Started=[DateTime]::UtcNow; Limit=$limit}
    } catch {
        $process.Dispose()
        Remove-Item -LiteralPath $directory -Recurse -Force -ErrorAction SilentlyContinue
        throw
    }
}

function Start-ArosWorker {
    param([ValidateSet('Diagnostics','Send')][string]$Operation, [string]$Purpose, [object]$Payload = $null)
    if ($script:ActiveJob) { throw 'En åtgärd pågår redan.' }
    $script:ActiveJob = New-ArosWorkerJob -Operation $Operation -Purpose $Purpose -Payload $Payload
    Update-ArosBusyControls
}

function Invoke-ArosHeadlessDiagnostics {
    # Keep Job Object ownership and any stalled provider in an expendable worker,
    # even when the script is invoked from the technician's existing PowerShell.
    $job = New-ArosWorkerJob -Operation Diagnostics -Purpose Headless
    try {
        if (-not $job.Process.WaitForExit(120000)) { throw 'Diagnostiken överskred två minuter och stoppades.' }
        $result = Read-ArosJsonFile $job.ResultPath
        if ($null -eq $result -or -not $result.Ok) { throw 'Diagnostiken kunde inte slutföras.' }
        return $result.Data
    } finally {
        try { if (-not $job.Process.HasExited) { $job.Process.Kill(); [void]$job.Process.WaitForExit(1500) } } catch { }
        $job.Process.Dispose()
        Remove-Item -LiteralPath $job.Directory -Recurse -Force -ErrorAction SilentlyContinue
    }
}

function Remove-ArosWorker {
    param([switch]$Terminate)
    $job = $script:ActiveJob
    $script:ActiveJob = $null
    if ($null -eq $job) { return }
    try {
        if ($Terminate -and -not $job.Process.HasExited) { $job.Process.Kill(); [void]$job.Process.WaitForExit(1500) }
    } catch { }
    finally {
        $job.Process.Dispose()
        Remove-Item -LiteralPath $job.Directory -Recurse -Force -ErrorAction SilentlyContinue
    }
    Update-ArosBusyControls
}

function Start-ArosDiagnosticJob {
    param([string]$Purpose = 'View')
    $ui.txtDiagnosticStatus.Text = 'Samlar dator- och nätverksinformation. Du kan avbryta. Det kan ta upp till två minuter.'
    Set-ArosFooter 'Diagnostik pågår…'
    Start-ArosWorker -Operation Diagnostics -Purpose $Purpose
}

function Submit-ArosFormSnapshot {
    param([System.Collections.IDictionary]$Fields)
    $diagnosticText = ''
    if ($Fields.AttachDiagnostics -and $script:DiagnosticReport) { $diagnosticText = [string]$script:DiagnosticReport.Text }
    $fingerprint = Get-ArosHash (($Fields | ConvertTo-Json -Depth 4 -Compress) + "`n" + $diagnosticText)
    if ($fingerprint -eq $script:SuccessfulFingerprint) {
        $ui.txtFormStatus.Text = 'Detta formulär har redan bekräftats som skickat. Ändra innehållet eller välj Nytt formulär för ett nytt ärende.'
        return
    }
    if ($fingerprint -ne $script:PendingFingerprint) {
        $script:PendingRequestId = [guid]::NewGuid().ToString()
        $script:PendingPayload = New-ArosRequestPayload -Fields $Fields -RequestId $script:PendingRequestId -DiagnosticText $diagnosticText
        $script:PendingFingerprint = $fingerprint
    } elseif ($script:LastSendUncertain) {
        $choice = [Windows.MessageBox]::Show($window, 'Förra försöket kunde inte bekräftas. Meddelandet kan redan ha skickats. Kontakta helst servicedesk med referensen. Skicka samma formulär igen ändå? Det kan ge ett dubblettärende.', 'Skicka igen?', 'YesNo', 'Warning')
        if ($choice -ne [Windows.MessageBoxResult]::Yes) { return }
    }
    $script:LastSendUncertain = $false
    $ui.txtRequestReference.Text = 'Referens: ' + $script:PendingRequestId
    $ui.txtFormStatus.Text = 'Skickar formuläret. Vänta på bekräftelsen innan du stänger fönstret.'
    Set-ArosFooter 'Skickar till servicedesk…'
    Start-ArosWorker -Operation Send -Purpose Send -Payload $script:PendingPayload
}

function Invoke-ArosSendButton {
    if ($script:ActiveJob) { return }
    $fields = Get-ArosFormFields
    $errors = @(Get-ArosFormErrors $fields)
    if ($errors.Count -gt 0) { $ui.txtFormStatus.Text = $errors -join "`n"; return }
    if ($fields.AttachDiagnostics -and $null -eq $script:DiagnosticReport) {
        $script:FormSnapshot = $fields
        $ui.txtFormStatus.Text = 'Samlar diagnostik till formuläret. Formuläret skickas när insamlingen är klar. Du kan avbryta under Diagnostik.'
        Start-ArosDiagnosticJob 'FormSend'
    } else { Submit-ArosFormSnapshot $fields }
}

function Update-ArosWorker {
    $job = $script:ActiveJob
    if ($null -eq $job) { return }
    if (-not $job.Process.HasExited) {
        if (([DateTime]::UtcNow - $job.Started).TotalSeconds -gt $job.Limit) {
            $operation = $job.Operation; $purpose = $job.Purpose
            Remove-ArosWorker -Terminate
            if ($operation -eq 'Send') {
                $script:LastSendUncertain = $true
                $ui.txtFormStatus.Text = 'Svarstiden gick ut. Meddelandet kan redan ha skickats. Ring servicedesk och uppge referensen innan du försöker igen.'
            } else {
                $ui.txtDiagnosticStatus.Text = 'Insamlingen tog för lång tid och stoppades. Du kan försöka igen eller kontakta servicedesk utan diagnostik.'
                if ($purpose -eq 'FormSend') { $ui.txtFormStatus.Text = 'Diagnostiken tog för lång tid. Formuläret har inte skickats. Försök igen eller avmarkera Bifoga diagnostik.'; $script:FormSnapshot = $null }
            }
            Set-ArosFooter 'Tidsgränsen nåddes. Se informationen på sidan.'
        } elseif ($job.Operation -eq 'Diagnostics' -and [IO.File]::Exists($job.ProgressPath)) {
            try {
                $progress = [IO.File]::ReadAllText($job.ProgressPath, [Text.Encoding]::UTF8)
                if ($progress.Length -gt 0 -and $progress.Length -lt 1000) { $ui.txtDiagnosticStatus.Text = $progress; Set-ArosFooter $progress }
            } catch { }
        }
        return
    }
    $result = $null
    try { $result = Read-ArosJsonFile $job.ResultPath } catch { }
    $operation = $job.Operation; $purpose = $job.Purpose
    Remove-ArosWorker
    if ($null -eq $result -or -not $result.Ok) {
        if ($operation -eq 'Send') {
            $script:LastSendUncertain = $true
            $ui.txtFormStatus.Text = 'Ingen giltig bekräftelse kunde läsas. Meddelandet kan redan ha skickats. Ring servicedesk med referensen innan du försöker igen.'
        } else {
            $ui.txtDiagnosticStatus.Text = 'Diagnostiken kunde inte slutföras. Prova igen eller kontakta servicedesk.'
            if ($purpose -eq 'FormSend') { $ui.txtFormStatus.Text = 'Diagnostiken kunde inte slutföras. Formuläret har inte skickats. Du kan avmarkera Bifoga diagnostik och försöka igen.'; $script:FormSnapshot = $null }
        }
        Set-ArosFooter 'Åtgärden kunde inte bekräftas. Se informationen på sidan.'
        return
    }
    if ($operation -eq 'Diagnostics') {
        $script:DiagnosticReport = $result.Data
        $ui.tbDiagnosticReport.Text = [string]$result.Data.Text
        $ui.txtDiagnosticStatus.Text = [string]$result.Data.Summary + ' Rapporten finns bara lokalt tills du sparar, kopierar eller skickar den.'
        Set-ArosFooter 'Diagnostiken är klar. Du kan läsa och spara rapporten.'
        Update-ArosBusyControls
        if ($purpose -eq 'FormSend') {
            $fields = $script:FormSnapshot; $script:FormSnapshot = $null
            Submit-ArosFormSnapshot $fields
        }
    } else {
        $ui.txtFormStatus.Text = [string]$result.Data.Message
        if ($result.Data.Status -eq 'Sent') {
            $script:SuccessfulFingerprint = $script:PendingFingerprint
            $script:LastSendUncertain = $false
            Set-ArosFooter 'E-poststeget har bekräftats. Referensen finns i formuläret.'
        } else {
            $script:LastSendUncertain = $result.Data.Status -eq 'Unknown'
            Set-ArosFooter 'Ingen bekräftelse på skickat meddelande. Se formuläret.'
        }
    }
}

function Show-ArosApplication {
    Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase
    $reader = [Xml.XmlNodeReader]::new([xml]$script:WindowXaml)
    try { $script:window = [Windows.Markup.XamlReader]::Load($reader) } finally { $reader.Close() }
    $script:ui = @{}
    $names = @('imgLogo','txtBrandSubline','navHome','navForm','navDiagnostics','navSettings','txtComputerName','btnCopyComputer','txtFooterStatus',
        'pageWelcome','pageHome','pageForm','pageDiagnostics','pageSettings','txtWelcomeHeading','imgWelcomeApps','imgWelcomeCloud','imgWelcomeSupport',
        'btnWelcomePortal','btnWelcomeOneDrive','btnWelcomeContinue','btnPhone','btnEmail','btnWeb','btnRemote','btnNewRequest','btnOpenDiagnostics',
        'tbContactName','tbContactEmail','tbContactPhone','tbCustomer','tbSubject','tbDescription','cbCategory','chkAttachDiagnostics','btnFormDiagnostics',
        'btnSend','txtFormStatus','txtRequestReference','btnClearForm','btnRunDiagnostics','btnCancelDiagnostics','btnSaveDiagnostics','btnCopyDiagnostics','tbDiagnosticReport','txtDiagnosticStatus',
        'pbFlowUrl','btnSaveSettings','btnClearEndpoint','txtEndpointStatus','tbSettingCustomer','txtSettingsHint')
    foreach ($name in $names) { $ui[$name] = $window.FindName($name); if ($null -eq $ui[$name]) { throw ('Gränssnittskontroll saknas: ' + $name) } }
    Initialize-ArosWindowAssets $window $ui $script:DataDirectory
    $ui.txtComputerName.Text = $env:COMPUTERNAME
    $ui.tbContactName.Text = $env:USERNAME
    $ui.txtBrandSubline.Text = 'Din IT. Nära till hands.'
    $script:ActiveJob = $null; $script:DiagnosticReport = $null; $script:FormSnapshot = $null
    $script:PendingFingerprint = ''; $script:SuccessfulFingerprint = ''; $script:LastSendUncertain = $false
    $script:PendingRequestId = ''; $script:PendingPayload = $null
    Refresh-ArosConfiguration
    if ($Mode -eq 'Setup') { Show-ArosPage 'Settings' }
    elseif ($Mode -eq 'Preview' -or -not (Test-ArosWelcomeSeen $script:WelcomePath $script:MachineKey)) { Show-ArosPage 'Welcome' }
    else { Show-ArosPage 'Home' }
    if ($Mode -eq 'Preview') { $window.Title = 'Aros Support – förhandsvisning'; Set-ArosFooter 'Förhandsvisning: första välkomsten förbrukas inte.' }
    else { Set-ArosFooter 'Aros IT-Partner · 021-152550 · Vardagar 08–17' }
    $workArea = [Windows.SystemParameters]::WorkArea
    $window.MinWidth = [Math]::Min($window.MinWidth, $workArea.Width)
    $window.MinHeight = [Math]::Min($window.MinHeight, $workArea.Height)
    $window.Width = [Math]::Min($window.Width, $workArea.Width)
    $window.Height = [Math]::Min($window.Height, $workArea.Height)

    $ui.navHome.Add_Click({ Show-ArosPage 'Home' })
    $ui.navForm.Add_Click({ Show-ArosPage 'Form' })
    $ui.navDiagnostics.Add_Click({ Show-ArosPage 'Diagnostics' })
    $ui.navSettings.Add_Click({ Show-ArosPage 'Settings' })
    $ui.btnWelcomeContinue.Add_Click({ Show-ArosPage 'Home' })
    $ui.btnWelcomePortal.Add_Click({ Invoke-ArosUiAction { Open-ArosLink 'companyportal:' } })
    $ui.btnWelcomeOneDrive.Add_Click({ [void][Windows.MessageBox]::Show($window, 'Klicka på OneDrive-molnet vid klockan och kontrollera att ditt arbetskonto är inloggat. Om OneDrive saknas: sök efter OneDrive i Start-menyn. Kontakta oss om du behöver hjälp.', 'Kontrollera OneDrive', 'OK', 'Information') })
    $ui.btnCopyComputer.Add_Click({ Invoke-ArosUiAction { Copy-ArosText $env:COMPUTERNAME 'Datornamnet är kopierat.' } })
    $ui.btnPhone.Add_Click({ Invoke-ArosUiAction { Copy-ArosText $script:Aros.Phone '021-152550 är kopierat. Ring oss vardagar 08–17.' } })
    $ui.btnEmail.Add_Click({ Invoke-ArosUiAction { Open-ArosLink ('mailto:' + $script:Aros.Email + '?subject=' + [Uri]::EscapeDataString('Support – ' + $env:COMPUTERNAME)) } })
    $ui.btnWeb.Add_Click({ Invoke-ArosUiAction { Open-ArosLink $script:Aros.SupportUrl } })
    $ui.btnRemote.Add_Click({ Invoke-ArosUiAction { Open-ArosLink $script:Aros.RemoteSupportUrl; Set-ArosFooter 'Fjärrsupport öppnas i webbläsaren. Hämta och starta programmet, och lämna koden till din Aros-tekniker.' } })
    $ui.btnNewRequest.Add_Click({ Show-ArosPage 'Form' })
    $ui.btnOpenDiagnostics.Add_Click({ Show-ArosPage 'Diagnostics' })
    $ui.btnRunDiagnostics.Add_Click({ Invoke-ArosUiAction { Start-ArosDiagnosticJob 'View' } })
    $ui.btnFormDiagnostics.Add_Click({ Invoke-ArosUiAction { Show-ArosPage 'Diagnostics'; if ($null -eq $script:DiagnosticReport) { Start-ArosDiagnosticJob 'View' } } })
    $ui.btnCancelDiagnostics.Add_Click({
        if ($script:ActiveJob -and $script:ActiveJob.Operation -eq 'Diagnostics') {
            $purpose = $script:ActiveJob.Purpose
            Remove-ArosWorker -Terminate
            $ui.txtDiagnosticStatus.Text = 'Insamlingen är avbruten. Ingen ny rapport har skickats.'
            if ($purpose -eq 'FormSend') { $ui.txtFormStatus.Text = 'Diagnostiken avbröts. Formuläret har inte skickats.'; $script:FormSnapshot = $null }
            Set-ArosFooter 'Diagnostiken avbröts.'
        }
    })
    $ui.btnSaveDiagnostics.Add_Click({ Invoke-ArosUiAction {
        $dialog = [Microsoft.Win32.SaveFileDialog]::new()
        $dialog.Filter = 'Textfil (*.txt)|*.txt'; $dialog.DefaultExt = '.txt'; $dialog.AddExtension = $true
        $dialog.FileName = 'Aros-Diagnostik-' + $env:COMPUTERNAME + '-' + (Get-Date -Format 'yyyyMMdd-HHmm') + '.txt'
        $dialog.InitialDirectory = [Environment]::GetFolderPath([Environment+SpecialFolder]::MyDocuments)
        if ($dialog.ShowDialog($window)) { [IO.File]::WriteAllText($dialog.FileName, [string]$script:DiagnosticReport.Text, [Text.UTF8Encoding]::new($true)); Set-ArosFooter ('Rapport sparad: ' + $dialog.FileName) }
    } })
    $ui.btnCopyDiagnostics.Add_Click({ Invoke-ArosUiAction { Copy-ArosText ([string]$script:DiagnosticReport.Text) 'Diagnostikrapporten är kopierad.' } })
    $ui.btnSend.Add_Click({ Invoke-ArosUiAction { Invoke-ArosSendButton } })
    $ui.btnClearForm.Add_Click({
        $ui.tbSubject.Clear(); $ui.tbDescription.Clear(); $ui.chkAttachDiagnostics.IsChecked = $false
        $ui.txtRequestReference.Text = ''; $ui.txtFormStatus.Text = 'Nytt formulär. Beskriv problemet och kontrollera kontaktuppgifterna.'
        $script:PendingFingerprint = ''; $script:SuccessfulFingerprint = ''; $script:LastSendUncertain = $false; $script:PendingPayload = $null
        [void]$ui.tbSubject.Focus()
    })
    $ui.btnSaveSettings.Add_Click({ Invoke-ArosUiAction {
        $path = $script:UserConfigPath; $protection = 'CurrentUser'
        if ($Scope -eq 'AllUsers') { $path = $script:MachineConfigPath; $protection = 'LocalMachine' }
        $newAddress = $ui.pbFlowUrl.Password
        if ($newAddress -and -not (Test-ArosEndpoint $newAddress.Trim())) { $ui.txtEndpointStatus.Text = 'Adressen måste vara en fullständig HTTPS-adress. Klistra in hela adressen från flödet.'; return }
        Save-ArosConfiguration -Path $path -Customer $ui.tbSettingCustomer.Text -NewEndpoint $newAddress -Protection $protection
        $ui.pbFlowUrl.Clear(); $newAddress = $null
        $ui.tbCustomer.Text = $ui.tbSettingCustomer.Text.Trim()
        Refresh-ArosConfiguration
        Set-ArosFooter 'Inställningarna är sparade. Inget testmeddelande har skickats.'
    } })
    $ui.btnClearEndpoint.Add_Click({ Invoke-ArosUiAction {
        $path = $script:UserConfigPath; $protection = 'CurrentUser'
        if ($Scope -eq 'AllUsers') { $path = $script:MachineConfigPath; $protection = 'LocalMachine' }
        Save-ArosConfiguration -Path $path -Customer $ui.tbSettingCustomer.Text -NewEndpoint '' -Protection $protection -ClearEndpoint
        $ui.pbFlowUrl.Clear(); Refresh-ArosConfiguration
        Set-ArosFooter 'Adressen för det valda omfånget är rensad. Övriga sparade inställningar gäller fortfarande.'
    } })
    $script:WelcomeRecorded = $false
    $window.Add_ContentRendered({
        if (-not $script:WelcomeRecorded -and $script:CurrentPage -eq 'Welcome' -and $Mode -ne 'Preview') {
            try { Set-ArosWelcomeSeen $script:WelcomePath $script:MachineKey; $script:WelcomeRecorded = $true }
            catch { Set-ArosFooter 'Välkomsten kunde inte markeras som visad. Den kan visas igen vid nästa start.' }
        }
    })
    $script:timer = [Windows.Threading.DispatcherTimer]::new()
    $script:timer.Interval = [TimeSpan]::FromMilliseconds(300)
    $script:timer.Add_Tick({
        try { Update-ArosWorker }
        catch {
            $wasSend = $script:ActiveJob -and $script:ActiveJob.Operation -eq 'Send'
            Remove-ArosWorker -Terminate
            if ($wasSend) { $script:LastSendUncertain = $true; $ui.txtFormStatus.Text = 'Resultatet kunde inte bekräftas. Meddelandet kan redan ha skickats. Kontakta servicedesk med referensen.' }
            else { $ui.txtDiagnosticStatus.Text = 'Insamlingen kunde inte slutföras.'; $ui.txtFormStatus.Text = 'Åtgärden kunde inte slutföras. Kontrollera informationen och försök igen.' }
            Set-ArosFooter 'Åtgärden kunde inte slutföras. Du kan fortfarande ringa servicedesk.'
        }
    })
    $window.Add_Closing({
        param($sender, $eventArgs)
        if ($script:ActiveJob -and $script:ActiveJob.Operation -eq 'Send') {
            $answer = [Windows.MessageBox]::Show($window, 'Formuläret skickas fortfarande. Om du stänger kan meddelandet ha skickats utan att bekräftelsen visas. Vill du stänga ändå?', 'Stäng Aros Support?', 'YesNo', 'Warning')
            if ($answer -ne [Windows.MessageBoxResult]::Yes) { $eventArgs.Cancel = $true; return }
        }
        $script:timer.Stop(); Remove-ArosWorker -Terminate
    })
    $script:timer.Start()
    try { [void]$window.ShowDialog() }
    finally { $script:timer.Stop(); Remove-ArosWorker -Terminate }
}

# Main entry point. No Windows UI is created in installer/worker/diagnostic modes.
if ([Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT) { throw 'Aros Support kräver Windows. Kör med Windows PowerShell 5.1 (powershell.exe).' }
if ($Install -and $Uninstall) { throw 'Välj antingen -Install eller -Uninstall.' }
if (-not $env:LOCALAPPDATA -or -not $env:ProgramData) { throw 'Windows användarprofil eller ProgramData saknas.' }
$script:DataDirectory = Join-Path $env:LOCALAPPDATA 'ArosIT\Support'
$script:UserConfigPath = Join-Path $script:DataDirectory 'settings.json'
$script:MachineConfigPath = Join-Path (Join-Path $env:ProgramData 'ArosSupport') 'settings.json'
$script:WelcomePath = Join-Path $script:DataDirectory 'welcome.json'
if ($Install) { Install-ArosSupport $Scope $Customer $FlowUrl; return }
if ($Uninstall) { Uninstall-ArosSupport $Scope; return }
if ($FlowUrl) { throw 'FlowUrl används bara med -Install. Öppna annars -Mode Setup för att spara adressen.' }
if ($Mode -eq 'Worker') {
    try {
        $job = Read-ArosJsonFile $JobFile
        if ($null -eq $job -or [string]::IsNullOrWhiteSpace($ResultFile)) { throw 'Bakgrundsuppgift saknas.' }
        if ($job.Operation -eq 'Diagnostics') { $data = Invoke-ArosDiagnostics -ProgressPath $ProgressFile }
        elseif ($job.Operation -eq 'Send') {
            $config = Get-ArosConfiguration $script:UserConfigPath $script:MachineConfigPath
            if ($config.Warning -or -not (Test-ArosEndpoint $config.Endpoint)) { throw 'Formuläret saknar giltiga inställningar.' }
            $data = Invoke-ArosSubmit -Payload $job.Payload -Endpoint $config.Endpoint
        } else { throw 'Okänd bakgrundsuppgift.' }
        Write-ArosJsonFile $ResultFile ([ordered]@{Ok=$true; Data=$data})
        exit 0
    } catch {
        if ($ResultFile) { try { Write-ArosJsonFile $ResultFile ([ordered]@{Ok=$false; Message='Åtgärden kunde inte slutföras.'}) } catch { } }
        exit 1
    }
}
if ($Mode -eq 'Diagnose') {
    if (-not $OutputPath) { $OutputPath = Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::MyDocuments)) ('Aros-Diagnostik-' + $env:COMPUTERNAME + '-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.txt') }
    $report = Invoke-ArosHeadlessDiagnostics
    [IO.File]::WriteAllText([IO.Path]::GetFullPath($OutputPath), [string]$report.Text, [Text.UTF8Encoding]::new($true))
    Write-Output ('Rapport sparad: ' + [IO.Path]::GetFullPath($OutputPath))
    return
}
if (-not [Environment]::UserInteractive -or [Diagnostics.Process]::GetCurrentProcess().SessionId -eq 0) { throw 'GUI måste startas i den inloggade användarens session. Installation med -Scope AllUsers kan köras som SYSTEM.' }
if ([Threading.Thread]::CurrentThread.GetApartmentState() -ne [Threading.ApartmentState]::STA) { throw 'Starta med powershell.exe -NoProfile -STA -File .\Aros-Support.ps1.' }
if ($Mode -eq 'Setup' -and $Scope -eq 'AllUsers' -and -not (Test-ArosAdministrator)) { throw 'Inställningar för alla användare kräver administratör. Starta PowerShell som administratör och kör kommandot igen.' }
[void][IO.Directory]::CreateDirectory($script:DataDirectory)
$script:MachineKey = Get-ArosMachineKey
if ($Mode -eq 'Welcome' -and (Test-ArosWelcomeSeen $script:WelcomePath $script:MachineKey)) { return }
$mutex = [Threading.Mutex]::new($false, ('Local\ArosSupport-' + (Get-ArosHash $env:USERNAME).Substring(0,16)))
$ownsMutex = $false
try {
    try { $ownsMutex = $mutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $ownsMutex = $true }
    if (-not $ownsMutex) {
        if ($Mode -ne 'Welcome') {
            Add-Type -AssemblyName PresentationFramework
            [void][Windows.MessageBox]::Show('Aros Support är redan öppet i din session. Använd det öppna fönstret, eller stäng det innan du startar en förhandsvisning eller inställningar för alla användare.', 'Aros Support', 'OK', 'Information')
        }
        return
    }
    Show-ArosApplication
} finally { if ($ownsMutex) { $mutex.ReleaseMutex() }; $mutex.Dispose() }
